  el: '#app',
  mixins: [helperUtil,
    helperMixin,
    documentUtil,
    poActionsUtil,
    ColorGenerator,
    displayFieldLabel,
    imageFieldSplitter,
    validationViewHelper,
    amountConversionHelper,
    doc_type_sub_type_Util,
    MultiScreenHelper,
    keyDownHelper,
    helper,
    cache,
  ],
  components: {
    
    Loader,
    supportForm,
    SubHeader,
    ScriptLogs,
    IgnoreTableValidation,
    BlockSupplier,
    DocumentLock,
    MessageBanner,
    CoaFields,
    AISeverityLevel,
    // InvoiceSaveExport,
    // FieldsView,
    SplitDocument,
    ErrorDocumentView,
    InvoiceDuplicateLock,
    // DocumentClassification,

    timeSpentTimer,
    AnnotationView,
    TaskList,
    UnBlockSupplier,
    NonMappedColumnsBtn,
  },
  watch: {
    $route(to, from) {
      if (!to.hasOwnProperty('path') || !from.hasOwnProperty('path')) {
        return;
      }
      const to_route = to.path.split('/');
      const from_route = from.path.split('/');
      // match for same route name
      if (
        to_route.length > 2 &&
        from_route.length > 2 &&
        to_route[1] === from_route[1] &&
        this.get_cached_data_id != this.docId
      ) {
        window.location.reload();
      }
    },
  },
  data() {
    return {
      docId: '',
      contact: this.$t('confirm_export'),
      showDialog: false,
      showExportDialog: false,
      zoom_value: ref(0.6),
      showArticlePage: false,
      disableSelectionButton: true,
      loading: false,
      shownButtonsLength: 0,
      showExpandButton: false,
      saveInstant: false,
      // enableExportButton: false,
      magnifyGlass: {} as any,
      allowedDoctypes: allowedDocTypes,
      format_warning_dismiss: {} as any,
      excluded_fields: ['fields_group'],
      account_block: '',
      error_message: '',
      currentDisplayedMessage: ref(''),
      trigger_document_lock: ref(false),
      isInvoiceDuplicate: ref(false),
      split_document: ref(false),
      headerFabIcon: ref(false),
      dropdownModel: ref(false),
      imageLoaded: ref(false),
      textConfirmation: false,
      selectMonitor: ref(false),
      doc_script_module_setting,

      barcode_amount: ref(0),
      barcode_data: ref({} as any),
      display_barcode_assignment: ref(false),
      barcode_field_set: ref({} as any),
      doc_fields: ref([] as any[]),
    };
  },
  beforeRouteLeave: async function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything

    await this.setDataToCache();
    this.removeBordersFromRectangles();
    this.removeAllConnectionLines();
    this.removeExistingConfirmationOverlays();
    this.removeMagnifier();
    notify.dismissAll();
    this.page = 1;
    if (this.external_window) {
      this.external_window.close();
    }

    if (typeof this.format_warning_dismiss === 'function') {
      this.format_warning_dismiss();
    }

    await this.releaseDocLock({ doc_id: this.record.doc_id });
    this.resetDocStore(to.fullPath);
    this.resetStoreOnRouteChange();
    next();
  },
  showDialog1: function () {
    setTimeout(() => {
      this.showDialog = true;
    }, 2000);
  },
  beforeMount: function () {
    this.renderComponent = false;
    this.isExtenedPanel = false;
  },
  mounted: function () {
    this.showLoading();
    this.connectWebSocket();
    this.init();
    this.show_all_menu_btns = true;
    this.isDebugFlagHandler();
    this.is_admin = isUserAdmin();

    let doc_id = this.$route.params.id as string;
    this.getDocAnnotations(doc_id);

    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);

    const splitter__before = $('.img-magnifier-container') as HTMLElement;
    if (splitter__before) {
      splitter__before.addEventListener('scroll', this.removeOverlayandLines);
    }

    const splitter__after = $('.q-splitter__after');
    if (splitter__after) {
      splitter__after.addEventListener('scroll', this.removeOverlayandLines);
    }

    document.addEventListener(
      'dispatch_status_bar_message',
      this.dispatchTaskbarMessage,
    );
    document.addEventListener(
      'highlight_table_row',
      this.highlightTableRowArea,
    );
    document.addEventListener('refresh_canvas', this.refreshCanvas);
    document.addEventListener(
      'set_splitter_model',
      this.setSplitterModelWrapper,
    );

    // this reference is beaing used from the child window
    (<any>window).FieldValidationView = this;
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    window.removeEventListener('keydown', this.keydownEvent);
    document.removeEventListener(
      'dispatch_status_bar_message',
      this.dispatchTaskbarMessage,
    );
    document.removeEventListener(
      'highlight_table_row',
      this.highlightTableRowArea,
    );
    document.removeEventListener(
      'removeSelectedAreaOnImage',
      this.removeSelectedAreaOnImage,
    );

    const splitter__before = $('.img-magnifier-container') as HTMLElement;
    if (splitter__before) {
      splitter__before.removeEventListener(
        'scroll',
        this.removeOverlayandLines,
      );
    }

    const splitter__after = $('.q-splitter__after');
    if (splitter__after) {
      splitter__after.removeEventListener('scroll', this.removeOverlayandLines);
    }

    try {
      this.screenshot = $('.screenshot') as HTMLElement;
      if (this.screenshot) {
        this.screenshot.removeEventListener('dblclick', this.dblClickToSelect);
        this.screenshot.removeEventListener('pointerdown', this.startDrag);
      }
    } catch (err) {
      logError('something went wrong while unmount', err);
    }

    document.removeEventListener('refresh_canvas', this.refreshCanvas);
    document.removeEventListener(
      'set_splitter_model',
      this.setSplitterModelWrapper,
    );
  },
  methods: {
    goRouteBack() {
      this.$router.go(-1);
    },
    prepareBarcodeData() {
      if (!this.record.hasOwnProperty('barcode_mapping')) {
        this.record.barcode_mapping = {};
      }
      this.barcode_field_set = JSON.parse(
        JSON.stringify(this.record.barcode_mapping),
      );
      this.doc_fields = [];
      this.barcode_amount = Object.keys(
        JSON.parse(JSON.stringify(this.record.barcode_data ?? {})),
      ).length;
      let barcode_list = JSON.parse(
        JSON.stringify(this.record.barcode_data ?? {}),
      );
      let index = 1;
      for (const [key, value] of Object.entries(barcode_list)) {
        (value as any).forEach((barcode: any) => {
          this.barcode_data[index] = barcode;
          index += 1;
        });
      }
      for (let field_info in this.formBuilderConfigModel) {
        let field = this.formBuilderConfigModel[field_info];
        if (
          field.fieldType == 'TextInput' ||
          field.fieldType == 'AmountFields'
        ) {
          if (field.hasOwnProperty('id')) {
            field['value'] = field['field_id'];
            field['label'] = this.$t(field['field_name']);
            this.doc_fields.push(field);
          }
        }
      }

      this.display_barcode_assignment = true;
    },
    setFieldData(barcode: any, field: any, index: number) {
      if (
        this.record.barcode_mapping[index] != null &&
        this.record.barcode_mapping[index] != undefined
      ) {
        let name = this.record.barcode_mapping[index].field_name;
        this.formBuilderModel[name].formatted_value = '';
        this.$refs.fieldsView.inputValueChanges(name);
      }

      if (field != null && field != undefined) {
        this.record.barcode_mapping[index] = field;
        this.formBuilderModel[field.field_name].formatted_value = barcode;
        this.$refs.fieldsView.inputValueChanges(field.field_name);
      }
    },
    dispatchTaskbarMessage(event: any) {
      if (!event.detail.message) {
        return;
      }
      this.currentDisplayedMessage = event.detail.message;
    },
    showNonMappedColumnsDialog() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }
      const event = new CustomEvent('show_non_mapped_columns_dialog', {});
      document.dispatchEvent(event);
    },
    deleteTable() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }

      this.record.tables = [];
      const event = new CustomEvent('delete_table', {});
      document.dispatchEvent(event);
    },
    addColumnInLineItems() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }
      const event = new CustomEvent('add_ai_new_column', {});
      document.dispatchEvent(event);
    },
    ZoomIn() {
      if (this.zoom_value >= 0.79) {
        return;
      }
      this.zoom_value = this.zoom_value + 0.1;
      this.zoom(this.zoom_value);
    },
    ZoomOut() {
      if (this.zoom_value <= 0.3) {
        return;
      }
      this.zoom_value = this.zoom_value - 0.1;
      this.zoom(this.zoom_value);
    },

    toggleSideBar(name: string) {
      if (this.current_sidebar == name) {
        this.toggleMenu();
        this.current_sidebar = '';
        return;
      }

      if (this.current_sidebar == '') {
        this.toggleMenu();
      }

      this.current_sidebar = name;
    },

    async improveDocuments() {
      try {
        if (this.isReadOnly) {
          return;
        }
        let res = await documentDetailApiService.improve_document_quality(
          this.docId,
        );
      } catch (err) {
        this.hideLoading();
        notify.error('There was an error improving the document');
        return;
      }
    },
    async init() {
      try {
        this.docId = this.$route.params.id as string;
        this.setAppType();

        await this.startSettingsFetch();
        await this.getInvoiceDataByDocId(this.docId);

        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false ||
          this.doc_fetch_error
        ) {
          this.hideLoading();
          return;
        }

        this.handleReadOnly();
        this.handleDocLockSubscribe();
        // this.getSplitterValue();
        this.getSplitterValueFromStorage();
        this.handleDuplicateInvoiceSettings();

        if (this.isReadOnly) {
          this.error_message = this.$t('READ_ONLY_MSG');
          this.trigger_document_lock = false;
        } else {
          this.trigger_document_lock = true;
        }

        this.initPage();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async handleDuplicateInvoiceSettings() {
      await this.fetchAttributes(this.record.doc_type);
      this.isInvoiceDuplicate = this.model[CONSTANTS.DUPLICATE_DETECTION];
      if (!this.isInvoiceDuplicate) {
        this.isInvoiceDuplicate =
          this.model[CONSTANTS.DUPLICATE_INVOICE_DETECTION];
      }
    },
    setInvoiceDuplicateStatus(status: boolean) {
      this.isInvoiceDuplicate = status;
    },
    setTriggerDocumentLock(isLocked: boolean) {
      this.trigger_document_lock = isLocked;
    },
    setCurrentPage() {
      this.lastPageItem = this.record.images.length;
    },
    setAppType() {
      setTimeout(() => {
        this.showDialog = false;
      }, 10000);
    },
    handleDocLockSubscribe() {
      const doc_lock_store = useDocLockStore();
      doc_lock_store.$subscribe((mutation, state) => {
        this.isReadOnly = !this.doc_lock?.success;
        this.handleReadOnly();
      });
    },
    handleReadOnly() {
      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
        return;
      }

      // check for access - pass the document to check permissions based on doc_type
      if (!Acl.canUpdate(this.record)) {
        this.isReadOnly = true;
      }
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        if ((await this.setRecordFromCache()) && this.record.doc_id === docId) {
          return;
        }

        // this.showLoading();
        this.record = [];
        this.clearSelectedSessionStorage();
        await this.getDocumentById(docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },
    getConfidence(confidence: number) {
      if (confidence) {
        return confidence < 1
          ? (+confidence.toFixed(2) * 100).toFixed(0)
          : +confidence.toFixed(2);
      }
      return '';
    },
    initPage() {
      this.handleFormatWarning();

      this.docType = this.record.doc_type;

      this.setImage();

      this.initImageArea();

      window.addEventListener('keydown', this.keydownEvent);
      document.addEventListener(
        'removeSelectedAreaOnImage',
        this.removeSelectedAreaOnImage,
      );

      this.getAI_IndicatorData();
      this.enableOrDisableExportButton();
      setTimeout(() => {
        this.setCurrentPage();
      }, 200);

      this.DOC_SCRIPT_MODULE =
        this.user_settings[this.doc_script_module_setting];
    },
    changeContentScroll(pos: any) {
      const scroller: any = document.querySelector('#validation_bar_content');
      var currentPos = scroller.scrollTop;
      scroller.scrollTop = currentPos + pos;
    },
    onScrollUp() {
      this.changeContentScroll(-110);
      const scroller: any = document.querySelector('#validation_bar_content');
      const subtracted_height = scroller.scrollHeight - scroller.clientHeight;
      var currentPos = scroller.scrollTop;
      if (currentPos == subtracted_height) {
        this.showScrollDownButton = false;
      } else {
        this.showScrollDownButton = true;
      }
      if (currentPos == 0) {
        this.showScrollUpButton = false;
      } else {
        this.showScrollUpButton = true;
      }
    },
    onScrollDown() {
      this.changeContentScroll(+110);
      const scroller: any = document.querySelector('#validation_bar_content');
      const subtracted_height = scroller.scrollHeight - scroller.clientHeight;
      var currentPos = scroller.scrollTop;
      if (currentPos == subtracted_height) {
        this.showScrollDownButton = false;
      } else {
        this.showScrollDownButton = true;
      }
      if (currentPos == 0) {
        this.showScrollUpButton = false;
      } else {
        this.showScrollUpButton = true;
      }
    },
    openPDfWindoByDefault() {
      if (
        this.user_settings[CONSTANTS.dual_monitor_mode_setting] &&
        this.isMultiScreen() &&
        this.pdf_in_window == false
      ) {
        this.selectBetweenMonitor();
      }
    },
    async isElementLoaded(selector: string) {
      while (document.querySelector(selector) === null) {
        await new Promise((resolve) => requestAnimationFrame(resolve));
      }
      return document.querySelector(selector);
    },

    async selectBetweenMonitor() {
      if (this.pdf_in_window == false) {
        if (this.isMultiScreen()) {
          const monitorPreference = await this.getUserBasedSettings(CONSTANTS.monitor_preference);
          if (monitorPreference) {
            let monitor = monitorPreference.slice(-1);
            let monitorNo: number = isNaN(Number(monitor)) ? 0 : +monitor - 1;
            this.openComponentInSeparateWindow(monitorNo);
          } else {
            this.selectMonitor = true;
          }
        } else {
          notify.error(
            this.$t('MULTI_SCREENS_NOT_FOUND'),
          );
        }

        return;
      }

      this.external_window.close();
      this.pdf_in_window = false;
      this.splitterModel = 80;
      this.prepareRectangles();
    },
    async openComponentInSeparateWindow(monitorNumber: number) {
      this.pdf_in_window = true;
      this.selectMonitor = false;
      this.splitterModel = 0;
      await this.setDataToCache();
      this.removeOverlayandLines();

      let route = this.$router.resolve({ path: '/show_pdf/' + this.docId });
      // this.external_window = window.open(route.href, '_blank', 'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1500,height=1000');
      this.openWindowOnSelectedMonitor(monitorNumber, route.href);
    },

    async routeToNextDoc(which: string) {
      this.showLoading();
      let response: any;
      try {
        let query = await this.makeQueryParamFromFilters();

        let queryParams =
          this.docId +
          '?sort_attr=created_on' +
          query +
          '&doc_type=' +
          this.docType;

        response =
          await documentDetailApiService.get_next_document(queryParams);

        if (response.success === true) {
          if (response.has_next === true && which === 'next') {
            notify.success(this.$t('NEXT_DOC_LOADED'));
            window.removeEventListener('beforeunload', this.onTabClose);
            await this.resetAllStoreData();
            this.$router.push('/field_validation_v1/' + response.next_id);
          } else if (response.has_previous === true && which === 'previous') {
            notify.success(
              this.$t('PREVIOUS_DOC_LOADED'),
            );
            window.removeEventListener('beforeunload', this.onTabClose);
            await this.resetAllStoreData();
            this.$router.push('/field_validation_v1/' + response.previous_id);
          } else {
            throw { message: 'NO_NEXT_DOC' };
          }
        } else {
          throw response;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    onTabClose(e: any) {
      let eventName = SessionStorage.has('event_name')
        ? (SessionStorage.getItem('event_name') as string)
        : null;
      if (eventName && eventName === 'language_change') {
        return;
      }
      e.preventDefault();
      e.returnValue = '';
      this.clearSelectedSessionStorage();
    },

    keydownEvent(e: any) {
      try {
        if (e.key === 'Escape') {
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();
          this.removeExistingConfirmationOverlays();
          this.restrictDrawing();
          this.removeMagnifier();
        } else if (e.key === 'Enter') {
          this.removeExistingConfirmationOverlays();
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();

          // setTimeout(() => {
          //   this.enableOrDisableExportButton();
          // }, 5);
          this.connectionId = '';
        } else if (e.key === 'ArrowDown') {
          this.removeExistingConfirmationOverlays();
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();
          this.$refs['fieldsView'].selectNextField(this.connectionId);
          setTimeout(() => {
            this.enableOrDisableExportButton();
          }, 5);
          this.connectionId = '';
        }
      } catch (e) {
        logInfo(e);
      }
    },

    async getAI_IndicatorData() {
      try {
        this.ai_fields =
          this.record && this.record.fields && Array.isArray(this.record.fields)
            ? this.record.fields.length
            : 0;

        let response: any;
        if (
          !this.record.filter_values ||
          !(this.record.filter_values.length > 0) ||
          !Array.isArray(this.record.filter_values)
        ) {
          throw 'getAI_IndicatorData () no filter_values or doc_type to proceed';
        }

        let query =
          '?doc_type=' +
          this.record.doc_type +
          '&filter_values=' +
          this.record.filter_values.join();

        response = await documentDetailApiService.get_ai_score(query);

        if (response.success === false) {
          throw response.message;
        }

        if (response.success === true) {
          this.ai_rules = response.rules;
          this.mean_effective_weight = response.mean_effective_weight;
          const event = new CustomEvent('FV_gauge_calculation', {
            detail: response,
          });
          document.dispatchEvent(event);
        }
      } catch (err) {
        logError(err);
      }
    },
    imageclicked(evt: any) {
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.record.images[evt.target.dataset.id].path);
      this.page = parseInt(evt.target.dataset.id) + 1;

      if (this.pdf_in_window) {
        this.pdfInChildPage();
      } else {
        this.pdfInSamePage();
      }
    },
    movePageUp() {
      if (this.page == this.lastPageItem) {
        notify.error(this.$t('page_limit_reached'));
        return;
      }
      this.page++;
      this.quickActionClicked(this.page);
    },
    movePageDown() {
      if (this.page == 1) {
        return;
      }
      this.page--;
      this.quickActionClicked(this.page);
    },

    downloadFile() {
      downloadDocumentFile(this.docId, this.record.filename, this.tokenQueryParam, '.pdf');
    },
    validatePageNumber() {
      if (!this.page) {
        this.page = 1;
        return;
      }

      if (this.page > this.lastPageItem) {
        this.page = this.lastPageItem;
      }

      this.quickActionClicked(this.page);
    },

    quickActionClicked(number: any) {
      if (!number || number == 0 || number > this.lastPageItem) {
        return;
      }

      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.record.images[number - 1].path);

      if (this.pdf_in_window) {
        this.pdfInChildPage();
      } else {
        this.pdfInSamePage();
      }
    },
    pdfInSamePage() {
      this.removeOverlayandLines();
      this.getImageDetails();
    },
    pdfInChildPage() {
      this.external_window.PdfView.image = this.image;
      this.external_window.PdfView.removeOverlayandLines();

      this.$nextTick(() => {
        this.external_window.PdfView.prepareRectangles();
      });
    },
    getImageDetails() {
      // if image or fields are not loaded return
      if (this.renderComponent == false || this.imageLoaded == false) {
        return;
      }

      let screenshot = this.screenshot;
      if (this.screenshot.offsetWidth == 0) {
        // hack for annotation view on . need a better solution
        screenshot = $('#screenshot2') as HTMLElement;
      }

      this.imageWidth = screenshot.offsetWidth;
      this.imageHeight = screenshot.offsetHeight;
      this.viewBox =
        '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);
      // this.checkForAnnotationViewDi();

      // this.setShowAllButtonsPanel();

      this.$nextTick(() => {
        this.prepareRectangles();
      });

      //remove the loader after image is loaded completed
      this.hideLoading();
      this.enableOrDisableExportButton();
    },

    assignImageDimenions() {
      // let imageElm2 = $('.validation-img-area') as HTMLElement;
      let imageElm = $('#image_container') as HTMLElement;
      if (imageElm) {
        let imageElm3 = imageElm.querySelector(
          '.q-splitter__before',
        ) as HTMLElement;
        this.imageWidth = imageElm.offsetWidth - 90;
        this.imageHeight = imageElm.offsetHeight - 32;
      }
      this.viewBox =
        '0 0 ' + String(this.imageWidth) + ' ' + String(this.imageHeight);
    },

    showConnectionFromRect(ev: any) {
      // this.connectionId = '';
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
      this.restrictDrawing();
      const connectionId: string = ev.target.getAttribute('connectionId');
      const rectElement = ev.target;
      const fieldElement = this.getElementToConnect(
        $('#' + connectionId) as HTMLElement,
      );
      this.scrollInToViewCenter(fieldElement as HTMLElement);
      this.scrollInToViewCenter(rectElement);
      document.documentElement.scrollTop = 0;

      setTimeout(() => {
        if (connectionId.startsWith(tableRowIdPreFix)) {
          rectElement.classList.add('svg-stroke-border');
          this.dsiplayFieldInToView(connectionId);
          return;
        }

        this.showConnection(connectionId, rectElement, fieldElement);
      }, 50);
    },
    highlightTableRowArea(e: any) {
      this.showConnectionFromField(e.detail, true);
    },
    showConnectionFromField(connectionId: string, isTableRow = false) {
      if (this.field_view_mode === 'annotate') {
        this.showNotification(this.$t('annotation_mode_is_on_warning'));
        return;
      }

      // this.connectionId = '';

      if (this.pdf_in_window) {
        this.external_window.PdfView.removeOverlayandLines();
        this.external_window.PdfView.restrictDrawing();
      } else {
        this.removeOverlayandLines();
        this.restrictDrawing();
      }

      // let connectionId: string = ev.target.closest('label').parentElement.getAttribute('id');

      let fieldElement: HTMLElement = this.getElementToConnect(
        $('#' + connectionId) as HTMLElement,
      ) as HTMLElement;
      if (!fieldElement) {
        return;
      }
      let pageNumber = Number(fieldElement.getAttribute('pageno'));
      pageNumber = isNaN(pageNumber) ? this.page : pageNumber;
      let pageNumberChanged = false;

      if (pageNumber && pageNumber !== this.page) {
        pageNumberChanged = true;
        this.page = pageNumber;

        this.image =
          this.baseUrl +
          '/' +
          cleanUpImagePath(this.record.images[this.page - 1].path);
        if (this.pdf_in_window) {
          this.sendMessegeToChildWindow('image', this.image, true);
        }
        this.getImageDetails();
        this.$forceUpdate();
      }
      this.connectionId = connectionId;

      // If page changed, then rendering IMAGE BASE 64 & plotting boxes on image take time.
      // If page changed, than show connection line after 400ms, otherwise render line immediately

      this.$nextTick(() => {
        setTimeout(
          () => {
            if (this.pdf_in_window) {
              this.external_window.PdfView.proceedForReactFinding(
                connectionId,
                fieldElement,
                isTableRow,
              );
            } else {
              this.proceedForReactFinding(
                connectionId,
                fieldElement,
                isTableRow,
              );
            }
          },
          pageNumberChanged ? 300 : 100,
        );
      });
    },
    proceedForReactFinding(
      connectionId: string,
      fieldElement: Element,
      isTableRow: boolean,
    ) {
      let rectElement = $('#' + connectionId + '_rect');
      if (rectElement) {
        this.scrollInToViewCenter(rectElement as HTMLElement);
        document.documentElement.scrollTop = 0;
      }

      setTimeout(() => {
        if (isTableRow) {
          this.highlightRow(rectElement);
          return;
        }

        if (!rectElement) {
          this.proceedIfReactNotFound(fieldElement);
          return;
        }
        this.showConnection(connectionId, rectElement, fieldElement);
      }, 50);
    },
    proceedIfReactNotFound(fieldElement: Element) {
      if (this.record.extraction_method === 'ELECTRONIC_DOCUMENT') {
        return;
      }
      this.componentType = fieldElement.getAttribute('child_type') as string;

      let inputValue = '';

      if (this.componentType === 'checkbox') {
        inputValue = fieldElement.getAttribute('aria-checked') ? 'true' : '';
      } else {
        let input: HTMLInputElement | null = fieldElement.querySelector(
          this.componentType,
        );

        if (input) {
          inputValue = input.value;
        }
      }

      if (inputValue != '') {
        this.showNotification(
          this.$t('SELECT_AREA_NO_COORDINATES'),
        );
        const message_event = new CustomEvent('dispatch_status_bar_message', {
          detail: { message: this.$t('SELECT_AREA') },
        });
        document.dispatchEvent(message_event);
      } else {
        this.showNotification(this.$t('SELECT_AREA'));
        const message_event = new CustomEvent('dispatch_status_bar_message', {
          detail: { message: this.$t('SELECT_AREA') },
        });
        document.dispatchEvent(message_event);
      }

      if (this.pdf_in_window) {
        this.external_window.PdfView.enableDrawing();
        this.external_window.PdfView.connectionId = this.connectionId;
      } else {
        this.enableDrawing();
      }
    },

    /**
     * This connection line will perform three tasks
     * 1. Add border to rect, but we'll remove previous border first
     * 2. Add line from input to rect, but we'll remove previous line first
     * 3. Add an overlay to rect to decide whether co-ordinates are correct or not
     * @param ev
     */
    showConnection(connectionId: string, rectElement: any, fieldElement: any) {
      if (this.pdf_in_window) {
        this.external_window.PdfView.proceedForReactFinding(
          connectionId,
          fieldElement,
          false,
        );
        return;
      }
      if (rectElement && fieldElement) {
        this.drawOverlay(connectionId, rectElement);
        // Adding border to corresponding rectangle
        rectElement.classList.add('svg-stroke-border');

        // Drawling line
        this.connect(
          rectElement as HTMLElement,
          fieldElement as HTMLElement,
          '#26a69a',
          2,
        );
      } else {
        alert(this.$t('NO_MAPPING_AVAILABLE'));
      }
    },

    /**
     * Replace new overlay with the old one
     */
    saveOverlayResult() {
      this.cleanRectangles();
      if (this.pdf_in_window) {
        this.external_window.PdfView.redraw();
      } else {
        this.redraw();
      }
      this.getTextByCoordinates(this.rectCordinate);
    },
    /**
     *
     * @param element1
     * @param element2
     * @param color
     * @param thickness
     */
    connect(
      element1: HTMLElement,
      element2: HTMLElement,
      color: string,
      thickness: number,
    ) {
      // draw a line connecting elements
      const off1 = this.getOffset(element1);
      const off2 = this.getOffset(element2);
      // bottom right
      const x1 = off1.left;
      const y1 = off1.top + off1.height / 2;
      // top right
      const x2 = off2.right;
      const y2 = off2.top + off2.height / 2;
      // distance
      const length = Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
      // center
      const cx = (x1 + x2) / 2 - length / 2;
      const cy = (y1 + y2) / 2 - thickness / 2;
      // angle
      const angle = Math.atan2(y1 - y2, x1 - x2) * (180 / Math.PI);
      // Before adding line from selected record to input, lets first remove previous line
      this.removeAllConnectionLines();
      // Drawing new line
      const line = document.createElement('div');
      line.setAttribute('id', 'connection_line');
      line.style.cssText =
        'z-index: 102;padding:0px; margin:0px; height:' +
        thickness +
        'px; background-color:' +
        color +
        '; line-height:1px; position:absolute; left:' +
        cx +
        'px; top:' +
        cy +
        'px; width:' +
        length +
        'px; -moz-transform:rotate(' +
        angle +
        'deg); -webkit-transform:rotate(' +
        angle +
        'deg); -o-transform:rotate(' +
        angle +
        'deg); -ms-transform:rotate(' +
        angle +
        'deg); transform:rotate(' +
        angle +
        'deg);';
      document.body.appendChild(line);
    },
    async getTextByCoordinates(cordinates: RectCoordinateType) {
      const data = this.record;
      let formData = new FormData();

      let x1 = cordinates.startX / this.imageWidth;
      let y1 = cordinates.startY / this.imageHeight;
      let x2 = cordinates.endX / this.imageWidth;
      let y2 = cordinates.endY / this.imageHeight;

      formData.append('x0', x1.toString());
      formData.append('y0', y1.toString());
      formData.append('x1', x2.toString());
      formData.append('y1', y2.toString());

      formData.append('doc_id', data.doc_id);
      formData.append('page', this.page.toString());
      formData.append('field_name', this.connectionId);

      // formData.append('image_base64', data.images[page - 1].content);
      this.showLoading();

      let response: any;
      try {
        response = await documentDetailApiService.get_field_value(formData);

        this.textApiResponse = response;

        const coords = response.coords;

        if (
          !coords ||
          (coords[0].x === 0 &&
            coords[0].y === 0 &&
            response.formatted_value === '')
        ) {
          notify.error(
            this.$t('EMPTY_MAPPING_NOT_ALLOWED'),
          );
          if (this.pdf_in_window) {
            this.external_window.PdfView.prepareRectangles();
            this.external_window.PdfView.enableDrawing();
          } else {
            this.prepareRectangles();
            this.enableDrawing();
          }
          return;
        }

        // TODO only for invoices
        if (this.record.doc_type == 'INVOICE') {
          if (this.dontAsk) {
            if (this.textApiResponse.multi_line) {
              this.textConfirmationMsg = this.$t('isMultiLineConfirm');
            } else {
              this.textConfirmationMsg = this.$t('isdrawcorrect');
            }
            this.textConfirmation = true;
          } else {
            this.saveInstant = true;
          }
        } else {
          this.updateFieldData();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    updateFieldData() {
      this.$refs['fieldsView'].updateFieldData(this.textApiResponse);
      this.saveInstant = false;
      this.textApiResponse = null;
    },

    enableOrDisableExportButton(printFieldsError?: boolean) {
