    checkFieldInvalid(field: any, set_export_button = true) {
      // logInfo('checkFieldInvalid::field', field.name, field);
      if (
        field.is_valid === false &&
        !this.isFieldCalcualtedFromLayout(field.name) &&
        this.isfieldsNotDisplayed(field.name)
      ) {
        this.enableExportButton = false;
        this.fieldErrors[field.name] = this.getFieldLabel(
          this.formBuilderConfigModel[field.name],
          '',
        );
        return;
      }

      if (this.fieldErrors.hasOwnProperty(field.name)) {
        delete this.fieldErrors[field.name];
      }

      if (set_export_button && objLen(this.fieldErrors) === 0) {
        this.enableExportButton = true;
      }
