    isFieldCalcualtedFromLayout(field_name: string) {
      let calculated = false;
      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          if (subRow.field_name == field_name && subRow.calculation_formula) {
            calculated = true;
          }
        }
