    getOverlayHeadings() {
      // parentDiv is the parent div of input that holds value
      // In order to get that value, we need to hit parent first
      // from parent, we'll get value of input

      const parentDiv = $('#' + this.connectionId);
      if (!parentDiv) {
        return '';
      }

      const child_type = parentDiv.getAttribute('child_type') as string;
      if (!child_type) {
        return '';
      }
      this.componentType = child_type;

      // Getting input value
      let heading = '';

      let subHeading = '';

      if (this.componentType === 'checkbox') {
        // input = parentDiv.querySelector('.q-checkbox__bg');
        // let value = input!.getAttribute('aria-checked');
        subHeading = parentDiv.getAttribute('aria-label') as string;

        heading = 'Un-Checked';
        if (parentDiv.getAttribute('aria-checked') === 'true') {
          heading = 'Checked';
        }
      } else {
        const parentDivHeading = $('.' + this.connectionId);
        subHeading = parentDivHeading!.innerHTML;

        const input = parentDiv.querySelector(
          this.componentType,
        ) as HTMLInputElement;
        heading = input.value;
      }

      return heading + splitDelimiter + subHeading;
