import {
  CONSTANTS,
  GROUP_NAMES,
  LOW_CONFIDENCE,
  readOnlyDocStatus,
  doc_script_module_setting} from 'src/constants';
import {
  useSettingStore,
  useDocLockStore,
  useDocumentStore,
  useFormBuilderStore,
  useDocMasterDataLookUpStore,
  useFieldValuesSettingsStore,
  useFormBuilderSettingsStore,
  useDashboardStore,
  useAmountFormatStore,
  useLookupFunctionStore,
  useLineItemStore} from 'src/store/main';

import { formBuilderApiService } from 'src/services';
import scriptBtn from 'src/components/document/script/scriptBtn.vue';
import {
  formBuilderInputTypes,
  allowAbleModels,
} from 'src/formBuilder/formBuilderConstants';
import validationButtonPanelHelper from 'src/formBuilder/validationButtonPanelHelper';
import DocumentClassification from 'src/components/document/classification/main.vue';
import keyDownHelper from 'src/pages/ValidationScreen/components/keyboard/keyDownHelper';
import dialogDraggable from 'src/components/DialogDraggable.vue';
import { ApiExceptions } from 'src/exceptions/index';
import { isUserAdmin } from 'src/utils/UserDetails';
import { textValidator } from 'src/validatior/index';
import { api, getAuthorizationToken } from 'pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';

const $ = document.querySelector.bind(document);
let fuzzyMap = new Map();

export default defineComponent({
  el: '#app',
  mixins: [
    helperMixin,
    helperUtil,
    poActionsUtil,
    keyDownHelper,
    medi_fields_def,
    amountConversionHelper,
    displayFieldLabel,
    validationButtonPanelHelper,
  ],
  props: {
    // data: [] as any,
    renderOpenWindoIcon: {
      type: Boolean,
      default: false,
    },
    isPanelSection: {
      type: Boolean,
      default: false,
    },
    page: {
      type: Number,
      default: 1,
    },
  },
  emits: [
    'removeOldMapiingsAndDrawNew',
    'showConnectionFromField',
    'refreshCanvasAfterSelection',
    'setSplitterModel',
    'handleScroll',
    'setApiData',
    'setDocVersion',
    'getImageDetails',
    'enableOrDisableExportButton',
    'checkFieldInvalid',
  ],
  components: {
    
    scriptBtn,
    Loader,
    draggable: VueDraggableNext,
    DocumentClassification,
    masterDataLookup,
    dialogDraggable,
    SelectionPopup,
  },

  watch: {
    populate_row_to_view: {
      handler: function (newVal, oldVal) {
        if (newVal == false) {
          return;
        }
        this.populateMSDataFromPopup();
      },
    },
  },
  data() {
    return {
      // page: 1,
      docId: '',
      imageWidth: 0,
      imageHeight: 0,
      connectionId: '',
      charges: GROUP_NAMES.charges,
      itemsData: {} as dynamicObj,
      conversionFields: [] as any,
      showPoMatchWarning: ref(false),
      highlightFieldsMode: ref(false),
      origin_warning_alert: {} as any,
      showAllChargesFields: ref(false),
      showSelectionPopupDialog: false,
      selection_popup_data: {} as any,
      format_warning_dismiss: {} as any,
      // Not sure if that's needed
      classification_method_icons: {
        EDI: 'images/EDI.svg',
        FACTURX: 'images/FACTURX.svg',
        XRECHNUNG: 'images/XRECHNUNG.svg',
        PEPPOL: 'images/PEPPOL.svg',
      } as any,
      amount_fields_confidence_count: 0,
      debounceScriptCalculateFunc: {} as any,
      doc_script_module_setting,
      excluded_field_types: ['Label', 'ExportButton', 'HorizontalSeparator'],
    };
  },

  mounted: function () {
    this.initDefaultValues();
    this.docId = this.$route.params.id as string;
    this.is_admin = isUserAdmin();
    this.isViewSeparateComponent();
    this.init();

    (<any>window).CoaFields = this;
    // window.addEventListener('resize', this.windowResize);

    const validation_view = $('#validation_view');
    if (validation_view) {
      validation_view.addEventListener('keydown', this.keydownEventWrapper);
    }

    document.addEventListener(
      'script_calculate_func',
      this.scriptCalculateFuncWrapper,
    );
    document.addEventListener('model_updated', this.updateModelAttribute);
    document.addEventListener('reload_tables', this.reloadTable);
    // document.addEventListener('keydown',  this.keydownEventWrapper);
    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);
    document.addEventListener(
      'selection_popup_closed',
      this.selectionPopupClosed,
    );
    document.addEventListener(
      'selection_popup_selected',
      this.selectionPopupSelected,
    );
    document.addEventListener('display_fields_errors', this.displayFieldErrors);
    document.addEventListener('element_click', this.elementClick);
    document.addEventListener('splitter_changed', this.windowResize);
  },
  unmounted: function () {
    const validation_view = $('#validation_view');
    if (validation_view) {
      validation_view.removeEventListener('keydown', this.keydownEventWrapper);
    }
    // window.removeEventListener('resize', this.windowResize);
    document.removeEventListener(
      'script_calculate_func',
      this.scriptCalculateFuncWrapper,
    );
    document.removeEventListener(
      'selection_popup_selected',
      this.selectionPopupSelected,
    );
    document.removeEventListener(
      'selection_popup_closed',
      this.selectionPopupClosed,
    );
    document.removeEventListener('model_updated', this.updateModelAttribute);
    document.removeEventListener('reload_tables', this.reloadTable);
    // document.removeEventListener('keydown',  this.keydownEventWrapper);
    document.body.removeEventListener('click', this.mouseClicked, true);
    document.removeEventListener(
      'display_fields_errors',
      this.displayFieldErrors,
    );
    document.removeEventListener('element_click', this.elementClick);
    document.removeEventListener('splitter_changed', this.windowResize);
  },
  methods: {
    async saveMapping(coa_field: any, index: number) {
      try {
        const supplier_id = this.record.fields.find(
          (field: any) => field.name == 'customer_product_code',
        )?.value;
        if (!supplier_id) {
          notify.error(this.$t('SUPPLIER_ID_MISSING'));
          return;
        }
        const mapping_data = {
          supplier_id: this.record.fields.find(
            (field: any) => field.name == 'customer_product_code',
          )?.value,
          doc_characteristic_name:
            this.tableFields[index]['CHARACTERISTIC'].value,
          api_characteristic_name: coa_field['CHARACTERISTIC'].value,
        };
        const response = await this.saveMappingData(mapping_data);
        if (!response.success) {
          throw { message: response.message };
        }
        notify.success(this.$t('mapping_saved'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(this.$t(msg));
        logError(err);
      }
    },
    mapData() {
      this.coaMappingData.forEach((mapping: any) => {
        const table_field_index = this.tableFields.findIndex(
          (field: any) =>
            field['CHARACTERISTIC'].value ==
            mapping['supplier_characteristic_name'],
        );
        if (table_field_index == -1) {
          return;
        }
        const coa_field_index = this.coaFields.findIndex(
          (field: any) =>
            field['CHARACTERISTIC'].value == mapping['api_characteristic_name'],
        );
        if (coa_field_index == -1) {
          return;
        }

        const temp_element = this.tableFields[table_field_index];
        this.tableFields[table_field_index] = this.tableFields[coa_field_index];
        this.tableFields[coa_field_index] = temp_element;
      });
      this.compareAndMatchFields();
    },
    async getCoaMapping() {
      this.coaMappingData = [];
      try {
        const supplier_id = this.record.fields.find(
          (field: any) => field.name == 'customer_product_code',
        )?.value;
        if (!supplier_id) {
          throw { message: 'Customer Product Code not Found' };
        }
        const response: dynamicObj = await this.getCoaMappingApi(supplier_id);
        if (!response.success) {
          throw { message: response.message };
        }
        this.coaMappingData = response.data;
        this.mapData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(this.$t(msg));
        logError(err);
      }
    },
    onAccept(event: any) {
      event.stopPropagation();
      this.record['export_parameters'] = {
        doc_export_status: 'export',
        validate: false,
      };

      this.exportData();
    },
    resetValidatedFields() {
      this.tableFields.forEach((tableField: any) => {
        tableField['RESULT'].error = false;
      });
    },
    dragEnd(event: any) {
      this.resetValidatedFields();
      this.compareAndMatchFields();
    },
    validateEmailFields() {
      if (!this.rejectData['email']) {
        throw { message: 'email_required' };
      }
      if (!this.rejectData['reason']) {
        throw { message: 'reason_required' };
      }
    },
    async sendRejectEmail() {
      this.showLoading();
      try {
        this.validateEmailFields();
        this.record.fields.forEach((field: any) => {
          if (field.name == 'supplier_name') {
            if (field.content != '') {
              this.rejectData['supplier_name'] = field.content;
            }
          }
        });
        if (!this.rejectData['supplier_name']) {
          throw { message: 'SUPPLIER_NAME_MISSING' };
        }
        const response: dynamicObj = await this.rejectCoa(this.rejectData);
        if (!response.success) {
          throw { message: response.message };
        }
        if (this.isReadOnly) {
          return;
        }
        this.rejectDocument(this.record.doc_id);
        notify.success(this.$t('rejected_successfully'));
        this.routeToDashboard();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(this.$t(msg));
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    openMailPopUp() {
      this.showEmailPopUp = true;
    },
    formatCoaFields() {
      this.coaFields.forEach((coaField: any) => {
        coaField['MIN'].value = parseFloat(coaField['MIN'].value);
        coaField['MAX'].value = parseFloat(coaField['MAX'].value);
        coaField['RESULT'].value = parseFloat(coaField['RESULT'].value);
      });
      this.tableFields.forEach((tableField: any, index: number) => {
        const minFloat = parseFloat(tableField['MIN'].value);
        const maxFloat = parseFloat(tableField['MAX'].value);
        const resultFloat = parseFloat(tableField['RESULT'].value);
        tableField['MIN'].value = isNaN(minFloat)
          ? tableField['MIN'].value
          : minFloat;
        tableField['MAX'].value = isNaN(maxFloat)
          ? tableField['MAX'].value
          : maxFloat;
        tableField['RESULT'].value = isNaN(resultFloat)
          ? tableField['RESULT'].value
          : resultFloat;
      });
    },
    compareAndMatchFields() {
      this.tableFields.forEach((tableField: any, index: number) => {
        if (this.coaFields.length < index + 1) {
          return;
        }
        if (this.tableFields.length < index + 1) {
          return;
        }
        const coaField: dynamicObj = this.coaFields[index];
        let coaMinValue = coaField['MIN'].value;
        let coaMaxValue = coaField['MAX'].value;

        if (tableField['RESULT'].value == '') {
          return;
        }

        if (tableField['RESULT'].value > coaMaxValue) {
          tableField['RESULT'].error = true;
        }
        if (tableField['RESULT'].value < coaMinValue) {
          tableField['RESULT'].error = true;
        }
      });
    },
    async loadCoaFields() {
      if (this.record.coa_item && this.record.coa_item.length > 0) {
        this.coaFields = this.record.coa_item;
        this.hideLoading();
        return;
      }
      await this.getCoaFields();
    },
    async getCoaFields() {
      this.showLoading();
      try {
        this.coaFields = [];
        let product_code = '';
        this.record.fields.forEach((field: any) => {
          if (field.name == 'ITNO' || field.name == 'customer_product_code') {
            if (field.formatted_value != '') {
              product_code = field.formatted_value;
            }
          }
        });
        if (!product_code) {
          throw { message: 'invalid_item_number' };
        }
        const response: dynamicObj = await this.getResponseCoa(product_code);
        if (!response.success) {
          throw { message: response.message };
        }
        response.data[0].records.forEach((record: any) => {
          const coaFieldObj = {
            CHARACTERISTIC: { value: record['TX40'], error: false },
            MIN: { value: record['EVMN'], error: false },
            MAX: { value: record['EVMX'], error: false },
            RESULT: { value: record['EVTG'], error: false },
          };
          this.coaFields.push(coaFieldObj);
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(this.$t(msg));
        logError(err);
      } finally {
        this.formatCoaFields();
        this.hideLoading();
      }
    },
    downloadFile() {
      try {
        let path =
          DOC2API_URL +
          '/' +
          this.record['doc_path'] +
          '?' +
          this.tokenQueryParam;
        if (!path) {
          return;
        }

        // Assuming 'path' is the URL to the file
        fetch(path)
          .then((response) => response.blob())
          .then((blob) => {
            // Create a Blob URL
            const blobUrl = URL.createObjectURL(blob);
            // Create an anchor element
            const link = document.createElement('a');
            link.href = blobUrl;
            // Set the file name (you may need to extract this from the response headers)
            link.download = this.record['filename'];
            // Append the link to the document
            document.body.appendChild(link);
            // Trigger a click on the link to start the download
            link.click();
            // Remove the link from the document
            document.body.removeChild(link);
            // Revoke the Blob URL to free up resources
            URL.revokeObjectURL(blobUrl);
          })
          .catch((error: any) => {
            logError('Error downloading file:', error);
          });

        // var link = document.createElement('a');
        // // link.download = row['filename'];
        // link.setAttribute('download', row['filename']);
        // link.href = path;
        // document.body.appendChild(link);
        // link.click();
        // // Cleanup the DOM
        // document.body.removeChild(link);
      } catch (err) {
        logError(err);
      }
    },
    initDefaultValues() {
      this.isFormBuilderMode = false;
      this.formBuilderModel = {};
      this.formBuilderConfigModel = {};
      this.lookup_loading_fields = {} as dynamicObj;
      this.freeze_fields_change_event = false;
    },

    reloadTable() {
      this.renderKey++;
    },
    async init() {
      if (this.is_sep_view && this.get_cached_data_id === this.docId) {
        await this.setRecordFromCache();
      }

      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
      }

      await this.getFormBuilderLayout();
      await this.populateListsAndValues();
      if (!this.isModelReady()) {
        notify.error(
          'Document does not have layout. Please contact administrator',
        );
        this.hideLoading();
        return;
      }

      if (this.record.doc_type == 'INVOICE') {
        this.setConversionFields();
        this.fieldCaluclations();
      }

      this.initTableFields();
      await this.loadCoaFields();
      await this.getCoaMapping();

      this.createAutoTriggerDebounceFunc();

      this.renderComponent = true;
      this.$emit('getImageDetails');
      await this.setLineItemDetails();

      this.createScriptCalculateDebounceFunc();

      this.$nextTick(function () {
        this.$emit('setSplitterModel', this.isExtenedPanel);
        this.viewLoadCompleted();
      });

      this.DOC_SCRIPT_MODULE = await this.getSetting(this.doc_script_module_setting);
    },
    initTableFields() {
      this.tableFields = [];
      this.record.tables.forEach((table: any) => {
        table.rows.forEach((row: any) => {
          let tableFieldObj: dynamicObj = {};
          row.columns.forEach((column: any) => {
            if (column.name == 'CHARACTERISTIC') {
              if (tableFieldObj['CHARACTERISTIC'] === column.value) {
                return;
              }
              tableFieldObj['CHARACTERISTIC'] = {
                value: column.value,
                error: false,
              };
              return;
            }
            if (column.name == 'RESULT') {
              if (tableFieldObj['RESULT'] === column.value) {
                return;
              }
              tableFieldObj['RESULT'] = { value: column.value, error: false };
              return;
            }
            if (column.name == 'MIN') {
              if (tableFieldObj['MIN'] === column.value) {
                return;
              }
              tableFieldObj['MIN'] = { value: column.value, error: false };
              return;
            }
            if (column.name == 'MAX') {
              if (tableFieldObj['MAX'] === column.value) {
                return;
              }
              tableFieldObj['MAX'] = { value: column.value, error: false };
              return;
            }
            return;
          });
          this.tableFields.push(tableFieldObj);
        });
      });
    },
    createScriptCalculateDebounceFunc() {
      this.debounceScriptCalculateFunc = debounce(() => {
        logInfo('debounceScriptCalculateFunc called');
        this.applyScript();
      }, 3000);
    },

    updateScriptRequest() {
      this.updateRequestId();
      this.debounceScriptCalculateFunc.cancel();
    },

    createNewScriptRequest() {
      this.createScriptCalculateDebounceFunc();
      logInfo('debounceScriptCalculateFunc canceled and created new one');
      this.debounceScriptCalculateFunc();
    },
    viewLoadCompleted() {
      const stickyArea = $('.validation-sticky-area') as HTMLElement;
      const notStickyArea = $('.not-sticky-area') as HTMLElement;

      if (stickyArea && notStickyArea) {
        notStickyArea.style.paddingTop = stickyArea.clientHeight + 20 + 'px';
      }

      const el_field_scrolle = $('#field_scrolle');
      if (el_field_scrolle) {
        el_field_scrolle.addEventListener('scroll', this.handleScroll);
      }
    },

    prepareMediTable(fieldDef: any) {
      this.formBuilderConfigModel[fieldDef.name] = Object.assign({}, fieldDef);

      if (!this.record.tables || !this.record.tables[0]) {
        this.record.tables = [];

        let tableData = {
          name: fieldDef.name,
          rows: [],
        };

        this.formBuilderModel[fieldDef.name] = Object.assign({}, tableData);
        return;
      }

      let tableObj = {};

      this.record.tables.forEach((table: any) => {
        if ((table.name = fieldDef.name)) {
          tableObj = Object.assign({}, table);
          return;
        }
      });

      this.formBuilderModel[fieldDef.name] = Object.assign({}, tableObj);
    },
    prepareMultiCheckBox(fieldDef: any, field_model: any, field_name: string) {
      this.formBuilderConfigModel[fieldDef.name] = Object.assign({}, fieldDef);
      if (!field_model) {
        this.formBuilderModel[field_name] = [];
        this.formBuilderModel[field_name].page = '';
        this.formBuilderModel[field_name].color = '';
        this.formBuilderModel[field_name].score = '';
        this.formBuilderModel[field_name].value = '';
        this.formBuilderModel[field_name].coords = [];
        this.formBuilderModel[field_name].groupList = [];
        this.formBuilderModel[field_name].confidence = '';
        this.formBuilderModel[field_name].formatted_value = '';
        return;
      }
      if (field_model.highlight_field) {
        field_model.highlight_field = false;
        this.addFieldToHighlight(field_name);
      }
      this.formBuilderModel[field_name] = Object.assign({}, field_model);
    },
    prepareCheckboxesTable(fieldDef: any, data: any, layoutSettings: any) {
      fieldDef.tableBodyRows.forEach(
        (tableBodyRow: any, bodyRowsIndex: any) => {
          tableBodyRow.forEach((tableBodyColumn: any, bodyColumnIndex: any) => {
            let field_name = tableBodyColumn.name;

            // replace setting with updated field settings
            if (layoutSettings.hasOwnProperty(field_name)) {
              Object.assign(
                tableBodyColumn,
                this.cleanLayoutSettings(layoutSettings[field_name]),
              );
            }

            this.prepareModel(tableBodyColumn, data[field_name], field_name);
          });
        },
      );
    },
    makeModel() {
      this.fieldListToHighlight = [];

      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.record !== undefined) {
          this.record.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
            this.fieldsNotDisplayed[value.name] = value;
          });

          // prepare the list with updated field settings
          let layoutSettings = this.getUpdatedFieldSettings();
          let groupKey = '';

          for (const [index, group] of this.formLayout.entries()) {
            if (group.short_cut_key_2) {
              groupKey = group.short_cut_key_1 + group.short_cut_key_2;
              this.groupShortCutMap.set(groupKey, index);
            }

            for (let fieldDef of group.rows) {
              let field_name = fieldDef.name
                ? fieldDef.name
                : fieldDef.field_name;

              if (
                fieldDef.fieldType === formBuilderInputTypes.TABLE_OF_CHECKBOXES
              ) {
                this.prepareCheckboxesTable(fieldDef, data, layoutSettings);
                continue;
              }

              if (
                fieldDef.fieldType === formBuilderInputTypes.EXTRACTED_TABLE
              ) {
                this.prepareMediTable(fieldDef);
                continue;
              }

              if (
                fieldDef.fieldType === formBuilderInputTypes.MULTI_CHECK_BOX
              ) {
                this.prepareMultiCheckBox(
                  fieldDef,
                  data[field_name],
                  field_name,
                );
                continue;
              }

              // replace setting with updated field settings
              if (layoutSettings.hasOwnProperty(field_name)) {
                fieldDef = Object.assign(
                  fieldDef,
                  this.cleanLayoutSettings(layoutSettings[field_name]),
                );
              }

              this.prepareModel(fieldDef, data[field_name], field_name);
            }

            if (group.name === GROUP_NAMES.charges) {
              this.handleChargesFieldsVisibility(group);
            }
          }

          if (Object.keys(this.fieldsNotDisplayed).length >= 0) {
            this.record.fields.forEach((value: any, index: any) => {
              if (this.fieldsNotDisplayed.hasOwnProperty(value.name)) {
                this.record.fields[index].is_valid = true;
                delete this.fieldsNotDisplayed[value.name];
              }
            });
          }
          // TODO Do it at the end when page is completly ready
          this.prepareLayoutForTemplate();
          this.handleConfidenceAlert();
          this.setupLookup();
          this.$forceUpdate();
        }

        this.prepareLayoutData();

        resolve('done');

        if (this.highlightFieldsMode) {
          setTimeout(() => {
            this.highlightFields();
          }, 500);
        }
      });
    },
    prepareModel(fieldDef: any, field_model: any, field_name: string) {
      if (field_model) {
        this.setColor(field_model, fieldDef);
      } else {
        field_model = this.createEmptyField(field_name, fieldDef.input_type);
      }
      let fieldType = fieldDef.input_type
        ? fieldDef.input_type
        : fieldDef.fieldType;
      if (!fieldType) {
        return;
      }
      if (this.record.doc_type == 'INVOICE') {
        this.countAmountFieldsConfidence(field_model);
      }

      this.cleanCheckboxValue(field_model, fieldType.toLowerCase());

      if (
        !fieldDef.hasOwnProperty('tabIndex') ||
        isUndefinedOrNull(fieldDef.tabIndex)
      ) {
        fieldDef.tabIndex = 0;
      }

      if (field_model.highlight_field) {
        field_model.highlight_field = false;
        this.addFieldToHighlight(field_name);
      }

      this.formBuilderModel[field_name] = [];
      this.formBuilderConfigModel[field_name] = [];

      this.formBuilderModel[field_name] = Object.assign({}, field_model); //JSON.parse(JSON.stringify(field_model));
      this.formBuilderConfigModel[field_name] = Object.assign({}, fieldDef); //JSON.parse(JSON.stringify(fieldDef));

      if (field_model.hasOwnProperty('is_required')) {
        this.formBuilderConfigModel[field_name].is_required =
          field_model.is_required;
      }

      if (field_model.hasOwnProperty('force_validation')) {
        this.formBuilderConfigModel[field_name].force_validation =
          field_model.force_validation;
        if (field_model.force_validation == true) {
          this.formBuilderModel[field_name].validation_code =
            'FORCED_VALIDATION';
          this.formBuilderModel[field_name].validation_message =
            'Validation required';
        }
      }

      this.setTabIndexInList(fieldDef);
      this.handleListofValues(field_name);
      this.broadcastFieldChange(field_name);
      this.setFieldError(field_name);

      // delete all those fields which are not hidden
      if (fieldDef.is_hidden === false) {
        if (this.fieldsNotDisplayed.hasOwnProperty(field_name)) {
          delete this.fieldsNotDisplayed[field_name];
        }
      }
    },

    setupLookup() {
      try {
        this.lookup_configurations = new Map();
        if (
          !this.record.hasOwnProperty('layout') ||
          !this.record.layout.hasOwnProperty('lookup_configurations')
        ) {
          return;
        }

        if (!this.record.layout.lookup_configurations) {
          return;
        }
        for (const [
          index,
          item,
        ] of this.record.layout.lookup_configurations.entries()) {
          if (!item.hasOwnProperty('fields') || !Array.isArray(item.fields)) {
            continue;
          }
          for (const [index, field] of item.fields.entries()) {
            if (!field.is_searchable) {
              continue;
            }

            this.lookup_configurations.set(
              field.field_name,
              Object.assign(JSON.parse(JSON.stringify(field)), {
                lookup_dataset_name: item.lookup_dataset_name,
                fields: JSON.parse(JSON.stringify(item.fields)),
              }),
            );
          }
        }

        this.check_for_auto_trigger();
      } catch (e) {
        logError(e);
      }
    },

    handleListofValues(field_name: string) {
      if (
        !this.formBuilderConfigModel[field_name].hasOwnProperty(
          'list_of_values',
        )
      ) {
        return;
      }

      this.addNameToLovList(
        this.formBuilderConfigModel[field_name].list_of_values,
      );
    },

    addFieldToHighlight(fieldName: string) {
      this.fieldListToHighlight.push(fieldName);
    },
    highlightFields() {
      this.highlightFieldsMode = false;

      for (const fieldName of this.fieldListToHighlight) {
        let fieldElement = $('#' + fieldName) as HTMLElement;

        if (fieldElement.parentElement?.classList.contains('q-td')) {
          fieldElement = fieldElement.parentElement;
        }

        if (fieldElement) {
          fieldElement.classList.add('light-yellow-with-effect');
          setTimeout(() => {
            fieldElement.classList.remove('light-yellow-with-effect');
          }, 4000);
        }
      }
    },
    getUpdatedFieldSettings(): any {
      let layoutSettings: any = {};
      let groups = JSON.parse(JSON.stringify(this.record.layout.groups));

      groups.forEach((group: any, index: any) => {
        group.rows.forEach((row: any, index: any) => {
          row.forEach((subRow: any, index: any) => {
            let field_name = subRow.field_name;
            layoutSettings[field_name] = subRow;
          });
        });
      });

      return layoutSettings;
    },
    cleanLayoutSettings(layoutSetting: any): any {
      delete layoutSetting.name;
      delete layoutSetting.field;
      delete layoutSetting.field_name;
      delete layoutSetting.field_type;

      // remove the title as it might be changed from layout builder
      delete layoutSetting.title;
      delete layoutSetting.translation_key;

      return layoutSetting;
    },
    setTabIndexInList(fieldDef: any) {
      if (
        this.excluded_field_types.includes(fieldDef.fieldType) ||
        fieldDef.is_readonly == true ||
        fieldDef.is_hidden == true ||
        fieldDef.isDisabled == true
      ) {
        return;
      }

      let field_name = fieldDef.field_name || fieldDef.name;
      // if (field_name == 'mc_ath') {
      //   logInfo(fieldDef);
      // }
      const index = Number(fieldDef.tabIndex);

      if (!this.fields_tabindex_mapping.hasOwnProperty(index)) {
        this.fields_tabindex_mapping[index] = [];
      }
      this.fields_tabindex_mapping[index].push(field_name);
    },

    cleanCheckboxValue(field_model: any, type: string) {
      if (type != 'checkbox' && field_model.fieldType != 'CheckBox') {
        return;
      }

      if (
        field_model.formatted_value == 'true' ||
        field_model.formatted_value == true ||
        field_model.formatted_value == 'Y'
      ) {
        field_model.formatted_value = true;
      } else {
        field_model.formatted_value = false;
      }
    },

    setFieldError(field_name: string) {
      if (!this.formBuilderModel.hasOwnProperty(field_name)) {
        return;
      }

      const field_model = this.formBuilderModel[field_name];
      if (
        field_model.hasOwnProperty('is_valid') &&
        field_model.is_valid == true
      ) {
        return;
      }

      let input_error = '';
      if (
        field_model.hasOwnProperty('validation_code') &&
        field_model.validation_code &&
        field_model.validation_code !== ''
      ) {
        input_error = field_model.validation_code;
      }

      if (
        field_model.hasOwnProperty('validation_message') &&
        field_model.validation_message &&
        field_model.validation_message !== ''
      ) {
        input_error = field_model.validation_message;
      }

      this.setFieldInputError(field_name, input_error);
    },

    setColor(field_model: any, fieldDef: any) {
      fieldDef.color = '';
      if (!field_model.hasOwnProperty('is_valid')) {
        return;
      }

      if (field_model.extraction_method == 'MD') {
        fieldDef.color = 'extraction_method-border-left';
      } else if (field_model.is_valid) {
        fieldDef.color = CONSTANTS.success_border_left;
      } else {
        fieldDef.color = 'error-border-left';
      }
    },
    setConversionFields() {
      this.conversionFields = this.getConversionFields();
    },
    getField(name: string) {
      let foundField = {} as dynamicObj;
      if (this.record !== undefined) {
        for (const key in this.record.fields) {
          let field = this.record.fields[key];
          if (field.name == name) {
            foundField = field;
            break;
          }
        }
      }

      return foundField;
    },
    createEmptyField(name: string, type: string) {
      let value = type == 'checkbox' ? false : '';
      return {
        confidence: 0,
        name: name,
        field_name: name,
        value: value,
        formatted_value: value,
        content: value,
      };
    },
    saveMediImageFields() {
      let tableData = {} as dynamicObj;
      if (
        SessionStorage.has('table_data') &&
        SessionStorage.getItem('table_data') != null &&
        SessionStorage.getItem('table_data') != ''
      ) {
        let tableDataStr = SessionStorage.getItem('table_data');
        tableData = JSON.parse(tableDataStr as string);
      } else {
        tableData = { columns: [], table_areas: [] };
      }
    },
    prepareTableJson() {
      Object.keys(this.formBuilderModel).forEach((fieldName: any) => {
        if (
          this.formBuilderConfigModel[fieldName].fieldType ===
          formBuilderInputTypes.EXTRACTED_TABLE
        ) {
          this.record['tables'] = [] as any;
          this.record.tables.push(
            Object.assign({}, this.formBuilderModel[fieldName]),
          );
        } else if (
          this.formBuilderConfigModel[fieldName].fieldType ===
          formBuilderInputTypes.MULTI_CHECK_BOX
        ) {
          this.record.fields.push(
            Object.assign({}, this.formBuilderModel[fieldName]),
          );
          this.record.fields[this.record.fields.length - 1].name = fieldName;
        }
      });
    },
    downloadXML() {
      logInfo('RECORD', this.record);
    },
    async saveData() {
      try {
        if (this.isReadOnly) {
          return;
        }
        this.debounceScriptCalculateFunc.cancel();
        this.prepareTableJson();
        this.saveMediImageFields();
        this.showLoading();
        this.cleanupTableData(this.record);
        const response = await this.saveDocumentWithCoaFields(
          this.docId,
          this.coaFields,
        );
        if (response.success === false) {
          throw response;
        }

        this.setDataToCache();
        await this.makeModel();
        this.setFieldErrors(true);
        const event = new CustomEvent('prepare_rows', {});
        document.dispatchEvent(event);

        this.triggerOnSave();
        this.refreshCanvas();
        this.$forceUpdate();
        notify.success(this.$t('MSG_SAVE'));
        let formData = new FormData();
        let token: string = await getAuthorizationToken();
        formData.append('doc_id', this.record.doc_id);
        formData.append('org_id', getOrgId());
        formData.append('action_type', 'UPDATED');
        formData.append('current_status', this.record.status);
        formData.append('previous_status', this.record.status);
        formData.append(
          'action_description',
          'Modified the document and saved it.',
        );
        await axios.post(
          api.update_document_log + this.record.doc_id,
          formData,
          {
            headers: {
              Authorization: token,
            },
          },
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    validateRequiredFieldRules() {
      let is_validate = true;

      if (
        !this.record.hasOwnProperty('required_field_pairs') ||
        !Array.isArray(this.record.required_field_pairs) ||
        this.record.required_field_pairs.length == 0
      ) {
        return is_validate;
      }

      Array.from(this.record.required_field_pairs).forEach(
        (fields_list: any) => {
          let has_value = false;
          for (let field_name of fields_list) {
            // this.formBuilderModel[field_name].input_error = '';
            if (this.formBuilderModel[field_name].formatted_value) {
              has_value = true; // if atleast one of the field has value
            }
          }

          if (!has_value) {
            is_validate = false;
            const error_message =
              this.getRequirdFieldsErrorMessage(fields_list);

            for (let field_name of fields_list) {
              this.setFieldInputError(field_name, error_message);
            }
          }
        },
      );

      return is_validate;
    },

    getRequirdFieldsErrorMessage(field_list: any) {
      const fields_with_labels = [];
      for (let field_name of field_list) {
        fields_with_labels.push(
          this.getFieldLabel(
            this.formBuilderConfigModel[field_name],
            '',
          ),
        );
      }

      let error_message = this.$t('atleast_fill_one_field');
      error_message = error_message.replace('#', fields_with_labels.join(', '));
      return error_message;
    },

    async exportData() {
      if (this.isReadOnly) {
        return;
      }
      let response: any;
      try {
        if (await this.validateExportData()) {
          return;
        }

        let data: any = JSON.parse(JSON.stringify(this.record));

        this.cleanupDataforApi(data);
        this.cleanupTableData(data);
        this.showLoading();
        if (data.hasOwnProperty('table_data_copy')) {
          delete data['table_data_copy'];
        }
        let formData = new FormData();
        formData.append('data', JSON.stringify(data));

        response = await documentDetailApiService.validate_and_export(
          this.docId,
          formData,
        );

        if (response.success === true) {
          await this.dashboardFiltersAfterExport();
          this.routeToDashboard();
          return;
        }

        notify.error(response.message);

        if (response.hasOwnProperty('data')) {
          this.record = response.data;
          if (
            this.record.hasOwnProperty('doc_id') &&
            !this.record.hasOwnProperty('layout')
          ) {
            this.record.layout = data.layout;
          }
          this.setDocDataVariables();
          await this.handleExportError();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    cleanupTableData(data: any) {
      if (
        !(
          data.tables &&
          data.tables.length > 0 &&
          data.tables[0].hasOwnProperty('rows') &&
          data.tables[0].rows.length > 0
        )
      ) {
        return;
      }

      let columnDataStatusMap = new Map();

      // iterate table to check which column has data
      Array.from(data.tables[0].rows).forEach((row: any) => {
        Array.from(row.columns).forEach((column: any) => {
          if (column.is_extra_column) {
            if (columnDataStatusMap.has(column.name)) {
              if (columnDataStatusMap.get(column.name) === false) {
                if (column.formatted_value) {
                  columnDataStatusMap.set(column.name, true);
                }
              }
            } else {
              if (column.formatted_value) {
                columnDataStatusMap.set(column.name, true);
              } else {
                columnDataStatusMap.set(column.name, false);
              }
            }

            // delete column.is_extra_column;
          }
        });
      });

      // remove those column which do not have data and are marked as extra
      Array.from(data.tables[0].rows).forEach((row: any) => {
        row.columns = row.columns.filter((column: any) => {
          return !(
            columnDataStatusMap.has(column.name) &&
            columnDataStatusMap.get(column.name) === false
          );
        });
      });
    },

    async handlePoMatch() {
      if (!(await this.isPoSettingActivate(this.doctype))) {
        return;
      }
      this.showPoMatchWarning = false;
      this.navigateToPOMatch();
    },

    async handleCOA() {
      const response: dynamicObj = await this.saveAndValidate();
      if (response.success === false) {
        this.displayFieldErrors();
        notify.error(response.message);
        return;
      }
      this.$router.push('/certificate-of-analysis/' + this.record.doc_id);
    },

    async navigateToPOMatch() {
      const response: dynamicObj = await this.saveAndValidate();
      if (response.success === false) {
        this.displayFieldErrors();
        notify.error(response.message);
        return;
      }
      const po_match_route = await this.getPOUrl(this.record.doc_type);
      this.$router.push(po_match_route + this.record.doc_id);
    },

    async setLineItemDetails() {
      let TBL_EXT_VERSION = '';

      if (this.record.doc_type != 'XML_INVOICE') {
        TBL_EXT_VERSION = await this.getSetting('TBL_EXT_VERSION');
      }

      if (
        !this.record.tables ||
        this.record.tables.length == 0 ||
        isObjectEmtpy(this.record.tables)
      ) {
        if (
          TBL_EXT_VERSION !== undefined &&
          TBL_EXT_VERSION != '' &&
          TBL_EXT_VERSION == 'Version3'
        ) {
          this.tb_version = 'v3';
        }
        return;
      }

      if (
        this.record.tables[0].hasOwnProperty('version') &&
        this.record.tables[0].version == 'v3'
      ) {
        this.tb_version = 'v3';
      }
    },

    routeToDashboard() {
      this.$router.push('/dashboard');
    },

    displayFieldErrors() {
      this.handleExportError();
    },

    async validateExportData(focusOnFirstErrorField = true) {
      this.handleScroll();
      this.updateFieldErrors();

      const fields_has_errors = this.setFieldErrors(true);
      const validation_errors = await this.checkValidationError();
      const required_fields_errors = !this.validateRequiredFieldRules();

      return fields_has_errors || validation_errors || required_fields_errors;
    },

    async handleExportError() {
      this.setDataToCache();
      await this.makeModel();
      this.refreshCanvas();
      const fields_has_errors = this.setFieldErrors(false);
    },

    updateFieldErrors() {
      for (const [field_name, fieldDef] of Object.entries(
        this.formBuilderModel,
      )) {
        if (
          this.formBuilderConfigModel[field_name].is_required &&
          fieldDef.formatted_value &&
          fieldDef.validation_code === 'REQUIRED'
        ) {
          fieldDef.validation_code = '';
        }
      }
    },

    setFieldInputError(field_name: string, error_message: string) {
      this.formBuilderModel[field_name].input_error = error_message;
    },

    setFieldErrors(skipLowConfidance: boolean) {
      let fields_has_errors = false;

      for (const [field_name, fieldDef] of Object.entries(
        this.formBuilderModel,
      )) {
        this.setFieldInputError(field_name, '');

        if (
          this.formBuilderConfigModel[field_name].is_required &&
          !fieldDef.formatted_value
        ) {
          fields_has_errors = true;
          this.setFieldInputError(field_name, this.$t('field_required'));
          continue;
        }

        if (fieldDef.is_valid) {
          continue;
        }

        if (
          !fieldDef.validation_code ||
          (skipLowConfidance &&
            LOW_CONFIDENCE.includes(fieldDef.validation_code))
        ) {
          continue;
        }

        let error_message =
          this.formBuilderModel[field_name].validation_message;
        if (!error_message) {
          error_message = this.$t(
            fieldDef.validation_code,
          );
        }

        fields_has_errors = true;
        this.setFieldInputError(field_name, error_message);
      }

      return fields_has_errors;
    },

    async checkValidationError() {
      let fields_has_validation_errors = false;

      for (const [field_name, fieldDef] of Object.entries(
        this.formBuilderModel,
      )) {
        if (this.formBuilderConfigModel[field_name].fieldType !== 'TextInput') {
          continue;
        }

        let field_value = fieldDef.formatted_value;
        if (!field_value || field_value == '') {
          continue;
        }

        const fieldConfigModel = this.formBuilderConfigModel[field_name];
        let is_valid = true;
        let input_error = '';

        ({ is_valid, input_error } = await textValidator.init(
          fieldDef,
          fieldConfigModel,
        ));

        if (is_valid) {
          continue;
        }

        this.formBuilderModel[field_name].formatted_value = '';
        this.setFieldInputError(field_name, input_error);
        fields_has_validation_errors = true;
      }

      return fields_has_validation_errors;
    },

    isModelReady() {
      return objLen(this.formBuilderModel) !== 0;
    },

