    handleLookupAutoTrigger(field_name: string) {
      if (isUndefinedOrNull(field_name) || isEmptyString(field_name)) {
        return;
      }

      let check = this.get_lookup_type_for_changed_field(field_name);
      if (check == true) {
        this.get_groups_to_change();
        this.updateLookupFieldsStatusInGroups();
        this.debounceLookupAutoTriggerFunc();
      }
