    triggerOnSave() {
      this.changed_fields = [];
      this.groups_to_update = [];
      for (const field of this.fields_with_autotrigger) {
        if (!this.checkifFieldChangedForTrigger(field.field_name)) {
          let index = this.fields_with_autotrigger.indexOf(field);
          this.fields_with_autotrigger.splice(index, index);
        } else {
          this.changed_fields.push(field);
          this.trigger_lookup_flow = field.group.lookup_dataset_name;
        }
      }
      this.get_groups_to_change();
      this.updateLookupFieldsStatusInGroups();
      this.debounceLookupAutoTriggerFunc();
    },

    get_field_lookup_name(field_name: string) {
      for (let group in this.record.layout.lookup_configurations) {
        for (let group_field in this.record.layout.lookup_configurations[group]
          .fields) {
          if (
            this.record.layout.lookup_configurations[group].fields[group_field]
              .field_name == field_name
          ) {
            let fieldname: string =
              this.record.layout.lookup_configurations[group].fields[
                group_field
              ].lookup_field;
            return fieldname;
          }
        }
      }
      return field_name;
    },

