    htmlElementClick(connectionId: string) {
      if (
        this.formBuilderConfigModel[connectionId].fieldType ===
        formBuilderInputTypes.EXPORT_BUTTON
      ) {
        this.handleButtons(connectionId);
        return;
      }

      const fieldItem = $('#' + connectionId);
      if (fieldItem && fieldItem.closest('.validation-sticky-area')) {
        // if partent of field is sticky its means selected field is item number
        this.handleScroll();
        return;
      }
      this.showConnectionFromField(connectionId);
