    handleButtons(connectionId: string) {
      if (
        this.formBuilderConfigModel[connectionId].exportType == CONSTANTS.reject
      ) {
        this.rejectDocument(this.record.doc_id);
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType == CONSTANTS.save
      ) {
        this.saveData();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType ==
        CONSTANTS.po_match
      ) {
        this.handlePoMatch();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType == CONSTANTS.coa
      ) {
        this.handleCOA();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType ==
        CONSTANTS.save_rules
      ) {
        logInfo('save rules');
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType ==
        CONSTANTS.quotes_detail
      ) {
        this.$router.push('/quote-details/' + this.record.doc_id);
        return;
      }

      // Export data
      this.record['export_parameters'] = {
        doc_export_status: this.formBuilderConfigModel[connectionId].exportType,
      };
      this.exportData();
    },

