    // =========================================================================================

    onInputValueChanges(fieldName: string, fieldType: string) {
      if (this.freeze_fields_change_event) {
        return;
      }
      if (fieldType === 'delete_rule') {
        this.deleteRule(fieldName);
        return;
      } else if (fieldType === 'calculated') {
        this.updateImportJson(fieldName, null, this.page, 'calculated');
      } else if (fieldName == 'purchase_order') {
        this.record.is_purchase_order_changed = true;
      }
      this.removeSelectedAreaOnImage(fieldName);

      if (this.isFieldScriptCalculated(fieldName)) {
        this.updateScriptRequest();
      } else {
        const needs_script_call = this.handleScriptForNonCalcField();
        if (!needs_script_call) {
          this.handleLookupAutoTrigger(fieldName);
        }
      }

      this.inputValueChanges(fieldName);
      this.startTimer();
    },

    removeSelectedAreaOnImage(field_name: string) {
      if (this.isConfirmationBoxDisable) {
        const event = new CustomEvent('removeSelectedAreaOnImage', {});
        document.dispatchEvent(event);
        this.connectionId = field_name;
        this.removeConnectionFromModel(this.connectionId);
      }
    },

    removeConnectionFromModel(field_name: string) {
      this.record.fields.forEach((value: any, index: any) => {
        if (value.name === this.connectionId) {
          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign(
              {},
              JSON.parse(JSON.stringify(value)),
            );
          }

          const update_attr = {
            color: null,
            coords: null,
            confidence: 0,
            validation_code: null,
          };

          this.formBuilderModel[this.connectionId] = Object.assign(
            this.formBuilderModel[this.connectionId],
            update_attr,
          );
          this.record.fields[index] = Object.assign(
            this.record.fields[index],
            update_attr,
          );
        }
      });
    },

    async getFormBuilderLayout() {
      try {
        const prams = {
          doc_type: this.record.doc_type,
          sub_doc_type: this.record.sub_doc_type,
          doc_origin: this.record.doc_origin,
          include_layout_json: true,
        };
        await this.getLayoutTemplate(prams);

        if (this.formLayout) {
          await this.makeModel();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },
    updateModel(newField: any) {
      return;
    },

    isFieldScriptCalculated(field_name: string) {
      if (
        this.formBuilderConfigModel[field_name].hasOwnProperty(
          'run_script_on_change',
        ) &&
        this.formBuilderConfigModel[field_name].run_script_on_change === true
      ) {
        return true;
      }

      return false;
    },

    isFieldhasWorkflowEnabled(field_name: string) {
      if (
        this.formBuilderConfigModel[field_name].hasOwnProperty(
          'run_workflow_on_change',
        ) &&
        this.formBuilderConfigModel[field_name].run_workflow_on_change === true
      ) {
        return true;
      }

      return false;
    },

    handleScriptCalculatedFields(field_name: string) {
      try {
        if (!this.isFieldScriptCalculated(field_name)) {
          return;
        }
        this.record.apply_script_triggered_on_field = field_name;
        // this.debounceScriptCalculateFunc();
        this.createNewScriptRequest();
      } catch (err) {
        logError(err);
      } finally {
      }
    },

    handleScriptForNonCalcField() {
      if (
        this.api_request_id !== '' &&
        this.record.hasOwnProperty('apply_script_triggered_on_field') &&
        this.record.apply_script_triggered_on_field
      ) {
        logError(
          'handleScriptForNonCalcField',
          this.api_request_id,
          this.record.apply_script_triggered_on_field,
        );
        this.updateScriptRequest();
        this.createNewScriptRequest();
        return true;
      }
      return false;
    },

    scriptCalculateFuncWrapper(e: any) {
      let row_id = '';
      let column_name = '';
      if (e.detail.columnName) {
        column_name = e.detail.columnName;
      }
      if (e.detail.rowId) {
        row_id = e.detail.rowId;
      }
      this.record.apply_script_triggered_on_table_row = row_id;
      this.record.apply_script_triggered_on_table_field = column_name;
      this.debounceScriptCalculateFunc();
    },

    async applyScript() {
      try {
        this.auto_saved_done = false;
        this.auto_saving = true;
        this.script_api_timestamp = Date.now();
        const is_done = await this.applyScriptOnDocument();
        if (!is_done) {
          return;
        }

        let discard_response = false;

        for (const [field_name, fieldDef] of Object.entries(
          this.formBuilderModel,
        )) {
          let field_timestamp = 0;
          if (fieldDef.hasOwnProperty('update_timestamp')) {
            field_timestamp = fieldDef.update_timestamp;
          }
          if (field_timestamp > this.script_api_timestamp) {
            discard_response = true;
          }

          if (discard_response) {
            logInfo(
              'discard_response',
              field_name,
              fieldDef.formatted_value,
              field_timestamp,
              this.script_api_timestamp,
            );
          }
        }

        if (discard_response) {
          this.updateRequestId();
          this.createNewScriptRequest();
          return;
        }

        await this.updateRecordAfterScript();

        this.$emit('setDocVersion');
        this.setDataToCache();

        this.highlightFieldsMode = true;
        await this.makeModel();
        this.handleLookupAutoTrigger(
          this.record.apply_script_triggered_on_field,
        );
        this.setFieldErrors(false);
        this.refreshCanvas();
        const event = new CustomEvent('prepare_rows', {});
        document.dispatchEvent(event);
      } catch (err) {
        logError(err);
      } finally {
        this.auto_saving = false;
        this.auto_saved_done = true;
        setTimeout(() => {
          this.auto_saved_done = false;
        }, 10000);
      }
    },

    get_lookup_type_for_changed_field(field_name: string) {
      this.changed_fields = [];
      this.groups_to_update = [];
      if (!this.checkifFieldChangedForTrigger(field_name)) {
        return false;
      }

      let check = false;

      for (let group of this.record.layout.lookup_configurations) {
        if (
          isUndefinedOrNull(group.lookup_dataset_name) ||
          isEmptyString(group.lookup_dataset_name)
        ) {
          continue;
        }

        for (let group_field in group.fields) {
          if (
            group.fields[group_field].field_name == field_name &&
            group.fields[group_field].auto_trigger === true
          ) {
            this.groups_to_update.push({
              group: group,
              field_name: field_name,
              lookup_field: group.fields[group_field].lookup_field,
            });
            for (let field of group.fields) {
              this.changed_fields.push(field);
            }
            this.trigger_lookup_flow = group.lookup_dataset_name;
            check = true;
          }
        }
      }
      return check;
    },

    async preparing_group_change_call() {
      const updated_groups = {} as dynamicObj;

      for (let group in this.groups_to_update) {
        const config = this.groups_to_update[group].group;
        if (
          isUndefinedOrNull(
            this.groups_to_update[group].group.lookup_dataset_name,
          ) ||
          isEmptyString(
            this.groups_to_update[group].group.lookup_dataset_name,
          ) ||
          updated_groups.hasOwnProperty(this.groups_to_update[group].group.id)
        ) {
          continue;
        }

        const master_lookup_type =
          this.groups_to_update[group].group.lookup_dataset_name;
        updated_groups[this.groups_to_update[group].group.id] = true;

        const advance_filters = {} as dynamicObj;
        const id = uid();

        let field_name = this.groups_to_update[group].field_name;
        let lookup_field = this.groups_to_update[group].lookup_field;

        advance_filters[id] = {
          field: { field: lookup_field },
          operator: this.getFieldOperator(
            field_name,
            this.groups_to_update[group],
          ),
          search_text: this.formBuilderModel[field_name].formatted_value,
        };

        let resp: any = await this.autoTriggerSearchByField(
          advance_filters,
          master_lookup_type,
        );
        // no record or many record found it will be null
        if (resp != null) {
          const master_data_row = JSON.stringify(resp.data[0]);
          this.populateMasterDataFields(
            config,
            master_lookup_type,
            master_data_row,
          );
          this.lookup_loading_fields[field_name].lookup_found = true;
        } else {
          this.lookup_loading_fields[field_name].lookup_found = false;
          this.lookup_loading_fields[field_name].lookup_found_name =
            master_lookup_type;
        }
      }
      this.trigger_lookup_flow = '';
      this.saveFieldsStateForAutotrigger(this.record.fields);

      // call apply script
      this.updateScriptRequest();
      this.record.apply_script_triggered_on_field = '';
      this.debounceScriptCalculateFunc();
      this.updateLookupFieldsStatusInGroups(false, false);
    },

    getFieldOperator(field_name: string, group: any) {
      for (let field of group.group.fields) {
        if (
          field.field_name == field_name &&
          field.hasOwnProperty('search_operator') &&
          !isUndefinedOrNull(field.search_operator) &&
          !isEmptyString(field.search_operator)
        ) {
          return field.search_operator as string;
        }
      }
      return 'contains';
    },

    updateLookupFieldsStatusInGroups(enable = true, set_lookup_status = true) {
      for (let group in this.groups_to_update) {
        const config = this.groups_to_update[group].group;
        for (let [index, field] of config.fields.entries()) {
          this.handleLookupFieldStatus(
            field.field_name,
            enable,
            set_lookup_status,
          );
        }
      }
    },

    handleLookupFieldStatus(
      field_name: string,
      enable: boolean,
      set_lookup_status = true,
    ) {
      if (!this.formBuilderModel.hasOwnProperty(field_name)) {
        return;
      }

      if (!this.lookup_loading_fields.hasOwnProperty(field_name)) {
        this.lookup_loading_fields[field_name] = {} as dynamicObj;
      }
      this.lookup_loading_fields[field_name].lookup_loading = enable;
      if (set_lookup_status) {
        this.lookup_loading_fields[field_name].lookup_found = null;
        this.lookup_loading_fields[field_name].lookup_found_name = null;
      }
    },

    get_changed_fields(config: dynamicObj) {
      const lookup_fields = config.fields;
      for (let [index, field] of lookup_fields.entries()) {
        this.changed_fields.push(field);
      }
    },

    removeCurrentSelectedGroup(master_lookup_type: string) {
      this.groups_to_update = this.groups_to_update.filter((group: any) => {
        return group.group.lookup_dataset_name !== master_lookup_type;
      });
    },

    get_groups_to_change() {
      for (let data of this.fields_with_autotrigger) {
        for (let changed_field of this.changed_fields) {
          if (
            changed_field.field_name.toLowerCase() ==
              data.field_name.toLowerCase() ||
            changed_field.lookup_field.toLowerCase() ==
              data.lookup_field.toLowerCase()
          ) {
            if (
              !this.groups_to_update.some(
                (existingGroup: any) =>
                  existingGroup.group === data.group &&
                  existingGroup.field_name.toLowerCase() ===
                    changed_field.field_name.toLowerCase() &&
                  existingGroup.lookup_field.toLowerCase() ===
                    changed_field.lookup_field.toLowerCase(),
              )
            ) {
              this.groups_to_update.push({
                group: data.group,
                field_name: data.field_name,
                lookup_field: data.lookup_field,
              });
            }
          }
        }
      }
    },

    check_for_auto_trigger() {
      this.fields_with_autotrigger = [];
      for (let group of this.record.layout.lookup_configurations) {
        if (
          isUndefinedOrNull(group.lookup_dataset_name) ||
          isEmptyString(group.lookup_dataset_name)
        ) {
          continue;
        }

        for (let group_field in group.fields) {
          if (
            group.fields[group_field].auto_trigger === true &&
            !this.fields_with_autotrigger.some(
              (existingField: any) =>
                existingField.field_name.toLowerCase() ===
                  group.fields[group_field].field_name.toLowerCase() &&
                existingField.lookup_field.toLowerCase() ===
                  group.fields[group_field].lookup_field.toLowerCase() &&
                existingField.group === group,
            )
          ) {
            this.fields_with_autotrigger.push({
              field_name: group.fields[group_field].field_name,
              lookup_field: group.fields[group_field].lookup_field,
              group: group,
            });
          }
        }
      }
    },

    populateMSDataFromPopup() {
      this.changed_fields = [];
      this.groups_to_update = [];

      let config = this.master_data_fields_map.get(this.master_lookup_type);

      this.get_changed_fields(config);
      this.get_groups_to_change();
      this.removeCurrentSelectedGroup(this.master_lookup_type);

      this.populateMasterDataFields(
        config,
        this.master_lookup_type,
        this.master_data_row,
      );
      this.updateLookupFieldsStatusInGroups();
      this.preparing_group_change_call();
    },

    async populateMasterDataFields(
      config: dynamicObj,
      master_lookup_type: string,
      master_data_row: string,
    ) {
      try {
        this.closeMsDialog();
        this.showLoading();
        this.freeze_fields_change_event = true;
        // General Response-Data for all the respective Fields
        let jsonResponse = JSON.parse(master_data_row);
        const values = [];
        const lookup_fields = config.fields;
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field.field_name;
          const lookup_field = field.lookup_field.toLowerCase();
          if (
            jsonResponse.hasOwnProperty(lookup_field) &&
            this.conversionFields.includes(field_name) &&
            jsonResponse[lookup_field] != null
          ) {
            values.push({
              key: jsonResponse[lookup_field],
              value: jsonResponse[lookup_field],
            });
          }
        }

        let formatted_values = [] as dynamicObj[];
        if (values.length > 0) {
          formatted_values = await this.formatMultiValues(
            values,
            'en_US',
            this.amount_format_locale,
          );
        }

        const extraction_method = 'MD';
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field.field_name;
          const lookup_field = field.lookup_field.toLowerCase();
          if (!this.formBuilderModel.hasOwnProperty(field_name)) {
            continue;
          }

          if (
            jsonResponse.hasOwnProperty(lookup_field) == false ||
            jsonResponse[lookup_field] == null
          ) {
            continue;
          }

          let formatted_value = jsonResponse[lookup_field];
          if (
            this.conversionFields.includes(field_name) &&
            jsonResponse[lookup_field] != null
          ) {
            formatted_value = this.searchValueByKey(
              formatted_value,
              formatted_values,
            );
          }

          // if lookup_field has name with name_formatted_value then it will be used as formatted value
          if (jsonResponse.hasOwnProperty(lookup_field + '_formatted_value')) {
            formatted_value = jsonResponse[lookup_field + '_formatted_value'];
          }

          this.formBuilderModel[field_name].formatted_value = formatted_value;
          this.formBuilderModel[field_name].value = jsonResponse[lookup_field];
          this.formBuilderModel[field_name].color =
            'extraction_method-border-left';
          this.formBuilderModel[field_name].extraction_method =
            extraction_method;
          if (this.formBuilderModel[field_name].formatted_value) {
            this.setFieldInputError(field_name, '');
          }

          if (
            !this.isCurrentFieldPrimary(field_name) &&
            this.isContentChanged(
              this.formBuilderModel[field_name].content,
              jsonResponse[lookup_field],
            )
          ) {
            this.formBuilderModel[field_name].content =
              jsonResponse[lookup_field];
            this.formBuilderModel[field_name].confidence = 0;
            this.formBuilderModel[field_name].validation_code = null;
            this.formBuilderModel[field_name].coords = null;
          }

          this.setColor(
            this.formBuilderModel[field_name],
            this.formBuilderConfigModel[field_name],
          );
          this.updateImportJson(
            field_name,
            this.formBuilderModel[field_name].coords,
            this.page,
            extraction_method,
          );
        }

        this.resetMasterDataStore();
        this.refreshCanvas();
        this.validateExportData(false);
        setTimeout(() => {
          this.$emit('enableOrDisableExportButton');
        }, 5);
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
        this.freeze_fields_change_event = false;
      }
    },

    jumpToTable(event: any) {
      event.preventDefault();
      for (const [index, group] of this.formLayout.entries()) {
        if (!this.isGroupTable(index)) {
          continue;
        }
        this.focusOnTableGroup(index);
        break;
      }
