    findGroupShortcutkey(event: any) {
      const key = event.key;
      const combKey_list = ['shift', 'alt'];

      const comb_key = combKey_list.find((comb_key: any) => {
        const mapIndex = comb_key + key;
        return this.groupShortCutMap.has(mapIndex);
      });
      return comb_key;
    },

    focusOnGroupFromMap(event: any) {
      if (this.groupShortCutMap.size === 0) {
        return;
      }

      const comb_key = this.findGroupShortcutkey(event);
      if (!comb_key) {
        return;
      }

      const mapIndex = comb_key + event.key;
      const groupIndex = this.groupShortCutMap.get(mapIndex);
      if (
        groupIndex === null ||
        groupIndex === undefined ||
        groupIndex === ''
      ) {
        return;
      }
      event.preventDefault();
    },

    isGroupTable(groupIndex: string) {
      if (!this.formLayout[groupIndex].rows[0]) {
        return false;
      }
      return this.formLayout[groupIndex].rows[0].fieldType === 'ExtractedTable';
    },

    getFirstFieldOfGroup(groupIndex: string) {
      let field_name = '';
      let exclude_field_types = ['CheckBox', 'TableOfCheckboxes'];
      exclude_field_types = exclude_field_types.concat(
        this.excluded_field_types,
      );

      const firstElement = this.formLayout[groupIndex].rows.find((row: any) => {
        return !exclude_field_types.includes(row.fieldType);
      });

      if (!firstElement) {
        return field_name;
      }

      field_name = firstElement.name;
      if (firstElement.hasOwnProperty('field_name')) {
        field_name = firstElement.field_name;
      }

      if (!field_name) {
        return '';
      }
      return field_name;
    },

    focusOnTableGroup(groupIndex: string) {
      const field = this.formLayout[groupIndex].rows[0];
      this.focusOnTable(field.name);
    },

    validateAllSectionFields(index: any) {
      if (this.isReadOnly) {
        return;
      }
      const section = this.formLayout[index];
      if (!section.hasOwnProperty('rows')) {
        logInfo('No rows found to validate in this section');
        return;
      }

      for (const fieldDef of section.rows) {
        this.validateField(fieldDef.field_name);
      }
    },

    getNextTabIndex(tab_Index: number): number {
      let found_index = false;
      let next_index = 0;
      for (const [key, value] of Object.entries(this.fields_tabindex_mapping)) {
        const current_index = Number(key);

        if (found_index === true) {
          next_index = current_index;
          break;
        }

        if (tab_Index === current_index) {
          found_index = true;
        }
      }

      const fields = this.fields_tabindex_mapping[next_index];
      if (!fields || !Array.isArray(fields)) {
        return this.getNextTabIndex(next_index);
      }

      return next_index;
    },

    isFieldAvailableToFocus(field_name: string) {
      const field_el: HTMLElement | null = $('#' + field_name);
      if (!field_el) {
        return false;
      }
      return true;
    },

    // same index, field is not valid then move to next field
    getNextTabIndexField(tabIndex: number, field_name: string): string {
      try {
        const fields = this.fields_tabindex_mapping[tabIndex];
        const field_index = fields.indexOf(field_name);

        if (field_index === fields.length - 1) {
          const next_tab_Index = this.getNextTabIndex(tabIndex);
          const first_field = String(
            this.fields_tabindex_mapping[next_tab_Index][0],
          );

          const is_available = this.isFieldAvailableToFocus(first_field);

          if (!is_available) {
            return this.getNextTabIndexField(next_tab_Index, first_field);
          } else {
            return first_field;
          }
        }

        const next_field_index = field_index + 1;
        const next_field_name = String(fields[next_field_index]);
        const is_available = this.isFieldAvailableToFocus(next_field_name);
        if (!is_available) {
          return this.getNextTabIndexField(tabIndex, next_field_name);
        }
        return next_field_name;
      } catch (err) {
        return '';
      }
    },

