    findGroupToFocus(groupIndex: number): number {
      const group = this.formLayout?.[String(groupIndex)];
      if (!group || !Array.isArray(group.rows)) {
        return groupIndex;
      }

      if (group.rows.length === 0) {
        return this.findGroupToFocus(groupIndex + 1);
      }

      if (group.is_stcky_group) {
        return this.findGroupToFocus(groupIndex + 1);
      }
      const field_name = this.getFirstFieldOfGroup(String(groupIndex));
      if (!field_name) {
        return this.findGroupToFocus(groupIndex + 1);
      }

      return groupIndex;
