    addAdditionalAmountPanelInRows() {
      let breakCheck = false;
      // let renderDefaultAmountField = true;
      let buttons_visibility: { [k: string]: any } = {};
      let buttons_hidden_fields: { [k: string]: any } = {};
      const fields_group = [
        {
          selected: false,
          is_hidden: false,
          name: 'additional_amount',
          icon: 'mdi:plus-circle-outline',
          field: 'additional_amount',
          label: 'additional_amount',
        },
        {
          selected: false,
          is_hidden: false,
          name: 'additional_amount_2',
          icon: 'mdi:plus-circle-outline',
          field: 'additional_amount_2',
          label: 'additional_amount_2',
        },
        {
          selected: false,
          is_hidden: false,
          name: 'additional_amount_3',
          icon: 'mdi:plus-circle-outline',
          field: 'additional_amount_3',
          label: 'additional_amount_3',
        },
        {
          selected: false,
          is_hidden: false,
          name: 'negative_amount',
          icon: 'mdi:minus-circle-outline',
          field: 'negative_amount',
          label: 'negative_amount',
        },
        {
          selected: false,
          is_hidden: false,
          name: 'negative_amount_2',
          icon: 'mdi:minus-circle-outline',
          field: 'negative_amount_2',
          label: 'negative_amount_2',
        },
        {
          selected: false,
          is_hidden: false,
          name: 'negative_amount_3',
          icon: 'mdi:minus-circle-outline',
          field: 'negative_amount_3',
          label: 'negative_amount_3',
        },
      ];

      for (const [index, group] of this.formLayout.entries()) {
        if (group.name === GROUP_NAMES.tax_details) {
          for (const [index2, subRow] of group.rows.entries()) {
            const field_name = subRow.field_name;

            if (field_name == 'fields_group') {
              breakCheck = true;
            }

            if (field_name == 'additional_amount' && !breakCheck) {
              group.rows.splice(index2, 0, {
                field_name: 'fields_group',
                def: fields_group,
              });

              breakCheck = true;
            }

            for (const [btnIndex, button] of fields_group.entries()) {
              let fieldName = button.field;

              if (fieldName === field_name) {
                button.label = this.displayFieldLabel(subRow);
                // if field is hidden
                if (subRow.is_hidden) {
                  buttons_hidden_fields[button.name] = field_name;
                } else if (this.formBuilderModel[field_name].value) {
                  subRow.visibile = true;
                  // renderDefaultAmountField = false;
                  buttons_visibility[button.name] = true;
                  this.formBuilderConfigModel[field_name].visibile = true;
                } else {
                  subRow.visibile = false;
                  this.formBuilderConfigModel[field_name].visibile = false;
                }
              }
            }
          }
        }
      }

      for (const [index, group] of this.formLayout.entries()) {
        if (group.name === GROUP_NAMES.tax_details) {
          for (const [index2, subRow] of group.rows.entries()) {
            const field_name = subRow.field_name;

            if (field_name == 'fields_group') {
              for (const [btnIndex, button] of subRow.def.entries()) {
                if (buttons_visibility[button.name] === true) {
                  button.selected = true;
                } else {
                  button.selected = false;
                }

                // if not found in list then hide button
                if (!buttons_hidden_fields[button.name]) {
                  button.is_hidden = true;
                }
              }
            }
          }
        }
      }
    },
    handleChargesFieldsVisibility(group: any) {
      this.showAllChargesFields = false;

      for (let index = 0; index < group.rows.length; index = index + 2) {
        try {
          const currentFielName = group.rows[index].field_name;
          if (index + 1 >= group.rows.length) {
            break;
          }
          const nextFielName = group.rows[index + 1].field_name;
          // If both fields in the row do not has data then hide it
          if (
            !this.formBuilderModel[currentFielName].value &&
            !this.formBuilderModel[nextFielName].value
          ) {
            group.rows[index].visibile = false;
            group.rows[index + 1].visibile = false;
          }
        } catch (err) {
          logError(
            err,
            index,
            group.rows[index],
            group.rows[index + 1],
            group.rows.length,
          );
        }
      }
    },
    toggleChargesFieldsVisibility(groupObj: any, showAllFields: boolean) {
      if (showAllFields) {
        this.showAllChargesFields = true;
        for (const [index2, subRow] of groupObj.rows.entries()) {
          subRow.visibile = true;
        }
      } else {
        this.handleChargesFieldsVisibility(groupObj);
      }
    },
    handleConfidenceAlert() {
      if (this.amount_fields_confidence_count > 1) {
        this.origin_warning_alert = notify.warning(
          this.$t('selection_popup_origin_warning'),
          5000,
        );
      }
    },

    toggleGroupFieldsVisibility(
      fieldName: string,
      group_row: any,
      btnIdx: any,
      hidden: boolean,
      group_name: any,
    ) {
      if (this.isButtonToggleDisable(this.record.status)) {
        return;
      }

      for (const group of this.formLayout) {
        if (group.name == group_name) {
          for (const subRow of group.rows) {
            let field_name = subRow.field_name;
            if (field_name == group_row.field_name) {
              subRow.def[btnIdx].selected = !hidden;
              // this.formBuilderConfigModel[field_name].def[btnIdx].selected = !hidden;
            }

            if (fieldName === field_name) {
              subRow.visibile = !hidden;
              // this.formBuilderConfigModel[field_name].visibile = !hidden;
            }
          }
        }
      }

      this.prepareLayoutForTemplate();
      // TODO refreshCanvas
      // this.refreshCanvas();
    },
    handleTabGroupLabels(group: any, group_name: string) {
      let fullIsVisible = false;
      let altLabels: { [k: string]: any } = {};

      if (
        (Object.keys(group).length === 0 &&
          Object.getPrototypeOf(group) === Object.prototype) ||
        group_name !== GROUP_NAMES.tax_details
      ) {
        return altLabels;
      }

      for (let button of group.buttons) {
        if (button.name == 'full' && button.selected === true) {
          fullIsVisible = true;
          break;
        }
      }

      if (fullIsVisible) {
        return altLabels;
      }

      for (let button of group.buttons) {
        if (button.name !== 'full' && button.selected === true) {
          altLabels = button.alt_translation_keys;
          break;
        }
      }
      return altLabels;
    },

    openSelectionPopup(data: any) {
      this.selection_popup_data['title'] = this.$t('selection_popup_heading');
      this.selection_popup_data['data'] = data;

      this.selection_popup_data['value_1'] = {
        key: 'suggested',
        value: data.formatted_value,
        disable: !data.value || data.value == '',
        label: this.$t('suggested_value'),
      };

      let other = data.extracted_value;
      this.selection_popup_data['value_2'] = {
        key: 'extracted',
        value: other.formatted_value,
        disable: !other.value || other.value == '',
        message: !other.message || other.message == '' ? '' : other.message,
        label: this.$t('extracted_value'),
      };
      this.showSelectionPopupDialog = true;
    },
    selectionPopupSelected(e: any) {
      if (
        !e.detail ||
        !e.detail.data ||
        !e.detail.data.data ||
        !e.detail.selected
      ) {
        return;
      }
      this.showSelectionPopupDialog = false;
      let field_data = e.detail.data.data;
      let coords = field_data.coords;

      if (e.detail.selected == 'extracted') {
        field_data = field_data.extracted_value;
      }

      this.formBuilderModel[this.connectionId].value = field_data.value;
      this.formBuilderModel[this.connectionId].formatted_value =
        field_data.formatted_value;
      this.formBuilderModel[this.connectionId].content = field_data.text;
      this.formBuilderModel[this.connectionId].api_save = true;

      this.updateCoordinates(coords);
      this.inputValueChanges(this.connectionId);

      this.$forceUpdate();
      this.hideLoading();

      // TODO only for invoices
      // this.prepareRectangles();
    },

    updateCoordinates(coordinates: any) {
      this.record.fields.forEach((value: any, index: any) => {
        if (value.name === this.connectionId) {
          value.coords = coordinates;
          value.page = this.page;
        }
      });
      this.$emit('refreshCanvasAfterSelection', this.connectionId);
    },

    selectionPopupClosed() {
      this.showSelectionPopupDialog = false;
      // TODO only for invoices
      // this.enableDrawing(true);
    },

    deleteRule(fieldName: string) {
      if (!this.record.hasOwnProperty('clear_rules_fields_for_user')) {
        this.record.clear_rules_fields_for_user = [] as any;
      }

      this.record.fields.forEach((value: any, index: any) => {
        if (value.name === fieldName) {
          this.record.clear_rules_fields_for_user.push(fieldName);
          this.record.fields.splice(index, 1);
        }
      });

      this.formBuilderConfigModel[fieldName].color = null;
      this.formBuilderModel[fieldName] = Object.assign(
        this.formBuilderModel[fieldName],
        {
          deleted: true,
          color: null,
          value: '',
          confidence: 0,
          formatted_value: '',
          content: null,
          validation_code: null,
          coords: null,
        },
      );

      // this.connectionId = fieldName;
      // this.initTempFieldDelete();
      this.refreshCanvas();
      this.handleLookupFieldStatus(fieldName, false, true);
      this.saveOneFieldStateForAutotrigger(this.record, fieldName);
      this.handleScroll();
      setTimeout(() => {
        this.$emit('enableOrDisableExportButton');
      }, 5);
    },

    refreshCanvas() {
      const event = new CustomEvent('refresh_canvas', {});
      document.dispatchEvent(event);
    },
  },
  setup() {
    let dataObj: any = [];
    let groupShortCutMap = new Map();

    const doc_line_items_store = useLineItemStore();
    const { tableRows } = storeToRefs(doc_line_items_store);

    const form_builder_store = useFormBuilderStore();
    const {
      freeze_fields_change_event,
      formBuilderModel,
      formLayout,
      isExtenedPanel,
      isFormBuilderMode,
      formBuilderConfigModel,
      renderComponent,
      docType,
      fieldListToHighlight,
    } = storeToRefs(form_builder_store);
    const {
      getElementWidth,
      prepareLayoutData,
      performCalulations,
      isFieldHidden,
      getLayoutTemplate,
    } = form_builder_store;

    const doc_store = useDocumentStore();
    const {
      record,
      script_api_timestamp,
      doc_loaded,
      get_cached_data_id,
      auto_saving,
      auto_saved_done,
      amount_format_locale,
      fieldsNotDisplayed,
      lookup_configurations,
      po_items,
    } = storeToRefs(doc_store);
    const {
      saveFieldsStateForAutotrigger,
      getCoaMappingApi,
      saveMappingData,
      getResponseCoa,
      rejectCoa,
      rejectDocument,
      saveOneFieldStateForAutotrigger,
      checkifFieldChangedForTrigger,
      saveDocumentWithCoaFields,
      applyScriptOnDocument,
      updateRecordAfterScript,
      setDataToCache,
      setRecordFromCache,
      saveAndValidate,
      cleanupDataforApi,
      setDocDataVariables,
      updateRequestId,
    } = doc_store;

    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const {
      model: ms_view_model,
      advance_filters: ms_advance_filters,
      master_lookup_type,
      changed_fields,
      groups_to_update,
      fields_with_autotrigger,
      selected_row: master_data_row,
      populate_row_to_view,
      master_data_fields_map,
      isDraggle,
    } = storeToRefs(doc_ms_data_lookup_store);
    const { resetMasterDataStore, isContentChanged, isCurrentFieldPrimary } =
      doc_ms_data_lookup_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    const {
      populateListsAndValues,
      getListOfValuesAsSelectList,
      addNameToLovList,
    } = field_values_setting_store;

    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { isConfirmationBoxDisable } = storeToRefs(
      form_builder_settings_store,
    );

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    const dashboard_store = useDashboardStore();
    const { dashboardFiltersAfterExport } = dashboard_store;

    const amount_format_store = useAmountFormatStore();
    const { formatMultiValues, searchValueByKey } = amount_format_store;

    const { tokenQueryParam } = useImageAuth();
    const lookup_function_store = useLookupFunctionStore();
    const { searchByField: autoTriggerSearchByField } = lookup_function_store;
    const { lookup_loading_fields, trigger_lookup_flow } = storeToRefs(
      lookup_function_store,
    );

    const settings_store = useSettingStore();
    const { getSetting } = settings_store;

    return {
      po_items,
      saveOneFieldStateForAutotrigger,
      trigger_lookup_flow,
      autoTriggerSearchByField,
      lookup_loading_fields,
      saveFieldsStateForAutotrigger,
      checkifFieldChangedForTrigger,
      freeze_fields_change_event,
      lookup_configurations,
      tokenQueryParam,
      script_api_timestamp,
      updateRecordAfterScript,
      isCurrentFieldPrimary,
      formatMultiValues,
      searchValueByKey,
      addNameToLovList,
      isFieldHidden,
      doc_loaded,
      getSetting,
      saveAndValidate,
      cleanupDataforApi,
      performCalulations,
      setDocDataVariables,
      amount_format_locale,
      setDataToCache,
      updateRequestId,
      getCoaMappingApi,
      setRecordFromCache,
      getLayoutTemplate,
      saveDocumentWithCoaFields,
      dashboardFiltersAfterExport,
      releaseDocLock,
      saveMappingData,
      resetMasterDataStore,
      applyScriptOnDocument,
      populateListsAndValues,
      getListOfValuesAsSelectList,
      getResponseCoa,
      rejectCoa,
      rejectDocument,

      master_lookup_type,
      changed_fields,
      groups_to_update,
      fields_with_autotrigger,

      isDraggle,
      tableRows,

      ms_advance_filters,
      isConfirmationBoxDisable,
      master_data_fields_map,
      populate_row_to_view,
      isContentChanged,
      master_data_row,
      ms_view_model,
      record,
      coaFields: ref([] as any),
      apiData: ref(dataObj),
      tableAreasStr: ref(''),
      is_sep_view: ref(false),
      fuzzyDialog: ref(false),
      selectedRow: ref([]),
      tableFields: ref([] as any),
      coaMappingData: ref([] as any),
      oldIndex: ref(0),
      showEmailPopUp: ref(false),
      rejectData: ref({
        email: '',
        reason: '',
      } as dynamicObj),
      isDragging: ref(false),
      indexToMove: ref(0),
      tableFieldsOriginal: ref([] as any),
      renderKey: 0,
      isReadOnly: ref(false),
      formBuilderModel,
      formLayout,
      isExtenedPanel,
      isFormBuilderMode,
      formBuilderConfigModel,
      get_cached_data_id,
      renderComponent,
      docType,
      groupShortCutMap: groupShortCutMap,
      fieldListToHighlight,
      fieldsNotDisplayed,
      tb_version: 'default',

      // funcations
      getElementWidth,
      prepareLayoutData,
      is_admin: ref(false),
      master_data_popup_width: ref('700'),
      fields_tabindex_mapping: ref({} as dynamicObj),
      script_loading: ref(false),
      auto_saving,
      auto_saved_done,

      DOC_SCRIPT_MODULE: ref(false),

      debounceLookupAutoTriggerFunc: {} as any,
    };
  },
});
</script>

